window.lessonData = [{"category": "Me and My Family", "topics": [{"title": "My Family (12 questions)", "slug": "myfamily", "level": "A1-A2", "questions": [{"original": "Tell me about your family. Who lives in your house?", "paraphrased": "Who are the people in your family?", "vocab": [{"word": "family", "definition": "the people who live with you and love you, like your mum, dad and brother", "translation": ""}, {"word": "house", "definition": "the building where you live with your family", "translation": ""}], "possibleAnswers": ["There are four people in my family: my mum, my dad, my sister and me.", "I live with my mum, my grandma and my little brother.", "My family is small. It is just me and my mum."]}, {"original": "Do you have any brothers or sisters in your family?", "paraphrased": "Tell me about your brothers and sisters.", "vocab": [{"word": "brother", "definition": "a boy who has the same mum and dad as you", "translation": ""}, {"word": "sister", "definition": "a girl who has the same mum and dad as you", "translation": ""}], "possibleAnswers": ["Yes, I have one brother. He is seven years old.", "No, I do not have brothers or sisters. I am the only child.", "I have two sisters. They are both older than me."]}, {"original": "What is your favourite thing to do with your family?", "paraphrased": "What do you enjoy doing together at home?", "vocab": [{"word": "favourite", "definition": "the thing you like the most", "translation": ""}, {"word": "enjoy", "definition": "to like something and have fun doing it", "translation": ""}], "possibleAnswers": ["I love playing board games with my family at the weekend.", "We watch funny films together on Friday night.", "I like it when we cook dinner together."]}, {"original": "Who is the oldest person in your family?", "paraphrased": "Tell me about the oldest person you know at home.", "vocab": [{"word": "oldest", "definition": "the person who has lived for the most years", "translation": ""}, {"word": "person", "definition": "a man, woman or child", "translation": ""}], "possibleAnswers": ["My grandma is the oldest. She is seventy-two.", "My grandpa is the oldest person in our family.", "I think my mum is the oldest because I am the youngest."]}, {"original": "Would you rather play a game with your family or read a book alone?", "paraphrased": "Do you prefer family games or quiet time by yourself?", "vocab": [{"word": "rather", "definition": "used to say what you prefer, or what you want more", "translation": ""}, {"word": "alone", "definition": "with nobody else; by yourself", "translation": ""}], "possibleAnswers": ["I would rather play a game with my family because it is so funny.", "I like reading alone in my room. It is quiet and nice.", "I would rather play a game, but sometimes I like being alone too."]}, {"original": "Tell me what you like to talk about with your mum or dad.", "paraphrased": "What do you chat about at home?", "vocab": [{"word": "talk", "definition": "to say things to someone, to have a conversation", "translation": ""}, {"word": "chat", "definition": "to talk in a friendly, relaxed way", "translation": ""}], "possibleAnswers": ["We talk about school and about my friends.", "I tell my mum about the games I play.", "My dad and I talk about football. We support the same team."]}, {"original": "What is your favourite meal that someone in your family makes?", "paraphrased": "What food does your family cook that you love?", "vocab": [{"word": "meal", "definition": "the food you eat at one time, like breakfast, lunch or dinner", "translation": ""}, {"word": "cooks", "definition": "makes food hot and ready to eat", "translation": ""}], "possibleAnswers": ["My mum makes lovely spaghetti. It is my favourite.", "I love my grandma's soup. She makes it on cold days.", "My dad makes great pancakes on Sunday morning."]}, {"original": "How do you help the people in your family?", "paraphrased": "What do you do to make things easier at home?", "vocab": [{"word": "help", "definition": "to do something for someone so their job is easier", "translation": ""}, {"word": "easier", "definition": "needing less work or effort; simpler to do", "translation": ""}], "possibleAnswers": ["I set the table for dinner every evening.", "I help my mum carry the shopping bags inside.", "I look after my little sister when my parents are busy."]}, {"original": "Have you ever been on a trip with your family?", "paraphrased": "Tell me about a fun journey with your family.", "vocab": [{"word": "trip", "definition": "a journey or visit to a place, usually for fun", "translation": ""}, {"word": "journey", "definition": "travelling from one place to another", "translation": ""}], "possibleAnswers": ["Yes, we went to the sea last summer. It was wonderful.", "We went to my aunt's house in the mountains.", "No, not yet. I hope we can go to the zoo one day."]}, {"original": "Who do you look like in your family?", "paraphrased": "Which family member looks similar to you?", "vocab": [{"word": "look like", "definition": "to have a similar face or appearance to someone", "translation": ""}, {"word": "similar", "definition": "almost the same, but not exactly", "translation": ""}], "possibleAnswers": ["Everyone says I look like my mum. We have the same eyes.", "I look like my dad. We both have curly hair.", "I do not think I look like anyone. Maybe a little like my grandma."]}, {"original": "If you could teach your family a new game, what would it be?", "paraphrased": "What game would you show your family how to play?", "vocab": [{"word": "teach", "definition": "to show someone how to do something so they can learn", "translation": ""}, {"word": "show", "definition": "to let someone see how something is done", "translation": ""}], "possibleAnswers": ["I would teach them a card game I learned at school.", "I would show my family how to play chess.", "I would teach them a game from my phone, but a simple one."]}, {"original": "How do you spend a normal weekend with your family?", "paraphrased": "Tell me about a usual weekend at your home.", "vocab": [{"word": "normal", "definition": "usual; happening most of the time", "translation": ""}, {"word": "usual", "definition": "what normally happens; what you do most often", "translation": ""}], "possibleAnswers": ["On Saturday we clean the house and then we go to the park.", "We usually visit my grandparents on Sunday.", "I do my homework and then we watch a film together."]}]}, {"title": "My Home and Bedroom (12 questions)", "slug": "myhomeandbedroom", "level": "A1-A2", "questions": [{"original": "Tell me about your bedroom. What is in it?", "paraphrased": "What things do you have in your room?", "vocab": [{"word": "bedroom", "definition": "the room where you sleep", "translation": ""}, {"word": "things", "definition": "objects; items you can see or touch", "translation": ""}], "possibleAnswers": ["In my bedroom I have a bed, a desk and a big bookshelf.", "There is a poster of my favourite band on the wall.", "My room is small, but it has a soft rug and a lamp."]}, {"original": "Is your bedroom only yours, or do you share it with someone?", "paraphrased": "Do you have your own room, or do you share it?", "vocab": [{"word": "share", "definition": "to use something together with another person", "translation": ""}, {"word": "own", "definition": "belonging to you and nobody else", "translation": ""}], "possibleAnswers": ["Yes, I share my room with my brother. He has the top bed.", "No, I have my own room. I love it.", "I share with my sister. Sometimes we talk late at night."]}, {"original": "What is your favourite place in your home?", "paraphrased": "Which room or spot do you like best at home?", "vocab": [{"word": "favourite", "definition": "the one you like the most", "translation": ""}, {"word": "place", "definition": "a position or area, like a room or a corner", "translation": ""}], "possibleAnswers": ["My favourite place is the kitchen because it smells nice.", "I love the sofa in the living room. I read there.", "My favourite place is the balcony. I can see the whole street."]}, {"original": "What colour are the walls in your bedroom?", "paraphrased": "Tell me the colour of your room's walls.", "vocab": [{"word": "colour", "definition": "how something looks to your eyes, like red, blue or green", "translation": ""}, {"word": "walls", "definition": "the flat sides of a room that go from the floor to the ceiling", "translation": ""}], "possibleAnswers": ["My walls are light blue. It makes me feel calm.", "They are white, but I have many colourful pictures on them.", "One wall is yellow and the others are white."]}, {"original": "Would you rather have a big window or a small window in your room?", "paraphrased": "Do you prefer a large or a small window?", "vocab": [{"word": "window", "definition": "the glass part in a wall where you look outside", "translation": ""}, {"word": "prefer", "definition": "to like one thing more than another", "translation": ""}], "possibleAnswers": ["I would rather have a big window because I love the light.", "A small window is fine. My room stays cool that way.", "A big window, so I can watch the birds in the tree."]}, {"original": "What do you keep on your desk in your bedroom?", "paraphrased": "Tell me about the things on your desk.", "vocab": [{"word": "keep", "definition": "to put something in a place and leave it there", "translation": ""}, {"word": "desk", "definition": "a flat table where you write, read or do homework", "translation": ""}], "possibleAnswers": ["I keep my pens, my notebook and a lamp on my desk.", "There is a photo of my family and a clock.", "My desk is quite tidy. I only keep my school things there."]}, {"original": "How do you usually tidy your bedroom at home?", "paraphrased": "What do you do to make your room clean and neat?", "vocab": [{"word": "tidy", "definition": "to put things in the right place so a room looks neat", "translation": ""}, {"word": "neat", "definition": "clean and in order; not messy", "translation": ""}], "possibleAnswers": ["I put my clothes in the wardrobe and my books on the shelf.", "First I pick up everything from the floor, then I make my bed.", "I tidy my room every Saturday morning."]}, {"original": "Is there a park or a shop near your home?", "paraphrased": "What can you find close to where you live?", "vocab": [{"word": "near", "definition": "close to; not far away", "translation": ""}, {"word": "close", "definition": "near; only a short distance away", "translation": ""}], "possibleAnswers": ["Yes, there is a small park just across the street.", "There is a bakery near us. It smells wonderful.", "A big shop is five minutes away on foot."]}, {"original": "Have you ever helped to paint a room in your home?", "paraphrased": "Tell me if you have painted a wall or a room.", "vocab": [{"word": "paint", "definition": "to cover a wall or object with colour using a brush", "translation": ""}, {"word": "wall", "definition": "the flat side of a room", "translation": ""}], "possibleAnswers": ["Yes, I helped my dad paint my room blue last year.", "I painted a small bookshelf with my mum. It was messy but fun.", "No, but I would love to paint a wall one day."]}, {"original": "How do you spend your time in your bedroom after school?", "paraphrased": "How do you spend your time in your room after school?", "vocab": [{"word": "after", "definition": "later than something; when something has finished", "translation": ""}, {"word": "spend", "definition": "to use your time doing something", "translation": ""}], "possibleAnswers": ["I do my homework first, and then I draw pictures.", "I like lying on my bed and listening to music.", "I play with my toys or read a comic."]}, {"original": "If you could change one thing in your room, what would it be?", "paraphrased": "What would you make different in your bedroom?", "vocab": [{"word": "change", "definition": "to make something different from how it is now", "translation": ""}, {"word": "different", "definition": "not the same as before; another kind", "translation": ""}], "possibleAnswers": ["I would add a bigger bookshelf for all my books.", "I would change my old lamp for a brighter one.", "I would like a soft chair where I can read."]}, {"original": "What sounds can you hear from your bedroom?", "paraphrased": "Tell me about the noises you hear in your room.", "vocab": [{"word": "sounds", "definition": "things you hear, like voices, music or birds", "translation": ""}, {"word": "hear", "definition": "to notice a sound with your ears", "translation": ""}], "possibleAnswers": ["I can hear birds singing in the morning.", "I hear cars and people in the street.", "At night it is very quiet. Sometimes I hear the wind."]}]}, {"title": "Pets and Animals (12 questions)", "slug": "petsandanimals", "level": "A1-A2", "questions": [{"original": "Do you have a pet? What is its name?", "paraphrased": "Tell me about an animal you keep at home.", "vocab": [{"word": "pet", "definition": "an animal you keep at home and look after, like a dog or a cat", "translation": ""}, {"word": "name", "definition": "the word you call someone or something", "translation": ""}], "possibleAnswers": ["Yes, I have a cat. Her name is Mimi.", "I have a dog called Rocky. He is very friendly.", "No, I do not have a pet, but I want a rabbit."]}, {"original": "What is your favourite animal, and why do you like it?", "paraphrased": "Which animal do you like most, and what do you like about it?", "vocab": [{"word": "animal", "definition": "a living creature like a dog, bird, fish or elephant", "translation": ""}, {"word": "why", "definition": "the reason for something; used to ask for a reason", "translation": ""}], "possibleAnswers": ["I love dolphins because they are clever and kind.", "My favourite animal is the rabbit. It is soft and quiet.", "I like parrots because they can talk and they are so colourful."]}, {"original": "If you could have any animal as a pet, what would you choose?", "paraphrased": "Which animal would you pick as a pet if you could?", "vocab": [{"word": "choose", "definition": "to decide which one you want", "translation": ""}, {"word": "pick", "definition": "to choose one thing from many", "translation": ""}], "possibleAnswers": ["I would choose a small monkey. It would be so much fun.", "I would pick a golden retriever dog. They are kind and friendly.", "I would choose a turtle. It lives a very long time."]}, {"original": "How often do you visit the zoo with your family?", "paraphrased": "Tell me how you feel about the zoo.", "vocab": [{"word": "zoo", "definition": "a place where many wild animals live so people can see them", "translation": ""}, {"word": "feel", "definition": "to have an emotion or opinion about something", "translation": ""}], "possibleAnswers": ["Yes, I love the zoo. I always want to see the elephants.", "It is nice, but I feel sad when the animals are in small cages.", "I like the zoo, especially the monkey house."]}, {"original": "Would you rather have a dog or a cat?", "paraphrased": "Do you prefer dogs or cats?", "vocab": [{"word": "dog", "definition": "a common pet animal that barks and likes to play", "translation": ""}, {"word": "cat", "definition": "a small pet animal with soft fur that says 'meow'", "translation": ""}], "possibleAnswers": ["I would rather have a dog because we can play in the park.", "I prefer cats. They are quiet and clean.", "Both are great, but I would choose a dog."]}, {"original": "Have you ever fed an animal with your own hands?", "paraphrased": "Tell me about giving food to an animal.", "vocab": [{"word": "fed", "definition": "gave food to someone or an animal (past of 'feed')", "translation": ""}, {"word": "food", "definition": "what people and animals eat", "translation": ""}], "possibleAnswers": ["Yes, I feed the birds in our garden every morning.", "I fed a horse carrots at my uncle's farm.", "I feed my fish little pieces of food before school."]}, {"original": "Which animals can you see in your town or city?", "paraphrased": "Which animals live around where you live?", "vocab": [{"word": "town", "definition": "a place with houses, shops and streets, bigger than a village", "translation": ""}, {"word": "city", "definition": "a very big town with many people and buildings", "translation": ""}], "possibleAnswers": ["I see pigeons, cats and sometimes a fox at night.", "There are many dogs in the park near my school.", "We have squirrels in the trees, and birds everywhere."]}, {"original": "What do you do to look after your pet?", "paraphrased": "How do you care for your animal at home?", "vocab": [{"word": "look after", "definition": "to take care of someone or an animal", "translation": ""}, {"word": "care", "definition": "the work of keeping someone or something safe and healthy", "translation": ""}], "possibleAnswers": ["I give my dog food and water, and I walk him every day.", "I clean my rabbit's box and give it fresh vegetables.", "I brush my cat and play with her in the evening."]}, {"original": "Which animal is the most interesting to you?", "paraphrased": "Tell me about an animal you find really interesting.", "vocab": [{"word": "interesting", "definition": "making you want to know more; not boring", "translation": ""}, {"word": "find", "definition": "to think or feel a certain way about something", "translation": ""}], "possibleAnswers": ["Octopuses are the most interesting. They have eight arms!", "I find bees interesting because they make honey.", "Penguins are interesting because they cannot fly but they swim very well."]}, {"original": "Which wild animal would you like to see one day?", "paraphrased": "Which wild animal would you love to watch one day?", "vocab": [{"word": "wild", "definition": "living in nature, not kept at home or on a farm", "translation": ""}, {"word": "watch", "definition": "to look at something carefully for some time", "translation": ""}], "possibleAnswers": ["I would love to see a lion in Africa.", "I want to watch whales in the sea. They are huge!", "I would like to see a panda eating bamboo."]}, {"original": "Are you scared of any animals, or do you like them all?", "paraphrased": "Tell me if any animals make you feel afraid.", "vocab": [{"word": "scared", "definition": "feeling afraid or frightened", "translation": ""}, {"word": "afraid", "definition": "feeling fear; scared", "translation": ""}], "possibleAnswers": ["A little. I am scared of big dogs that run fast.", "No, I like animals. But I keep away from bees.", "I am scared of spiders, but they are very small."]}, {"original": "What can we do to help animals that have no home?", "paraphrased": "How can people take care of animals without a family?", "vocab": [{"word": "help", "definition": "to do something good for someone or an animal", "translation": ""}, {"word": "home", "definition": "the place where you live; for animals, a safe place to stay", "translation": ""}], "possibleAnswers": ["We can give them food and water, or take them to an animal centre.", "We can be kind and not hurt them. We can tell an adult.", "My family gives old blankets to the animal shelter."]}]}, {"title": "Food I Like (12 questions)", "slug": "foodilike", "level": "A1-A2", "questions": [{"original": "What food do you love, and what food do you hate?", "paraphrased": "Tell me about the food you like and the food you dislike.", "vocab": [{"word": "love", "definition": "to like something very much", "translation": ""}, {"word": "hate", "definition": "to dislike something very much", "translation": ""}], "possibleAnswers": ["I love pizza and I hate fish. It smells funny.", "I love strawberries, but I really do not like onions.", "I love rice and chicken. I hate very hot, spicy food."]}, {"original": "What is your favourite fruit, and how often do you eat it?", "paraphrased": "Which fruit do you enjoy eating the most?", "vocab": [{"word": "favourite", "definition": "the one you like best", "translation": ""}, {"word": "fruit", "definition": "a sweet food from a plant, like an apple or a banana", "translation": ""}], "possibleAnswers": ["My favourite fruit is the mango. It is so sweet.", "I love apples, especially the red ones.", "Bananas are my favourite because they give me energy."]}, {"original": "How do you feel about cooking food for your family at home?", "paraphrased": "Tell me if you enjoy making food as well as eating it.", "vocab": [{"word": "cooking", "definition": "making food ready to eat, using heat", "translation": ""}, {"word": "eating", "definition": "putting food in your mouth and swallowing it", "translation": ""}], "possibleAnswers": ["I like cooking simple things, like eggs and pasta.", "I prefer eating! But I help my mum sometimes.", "I love cooking with my grandma. We make cakes together."]}, {"original": "What do you usually eat for breakfast in the morning?", "paraphrased": "Tell me about your normal morning meal.", "vocab": [{"word": "usually", "definition": "most of the time; what you normally do", "translation": ""}, {"word": "breakfast", "definition": "the first meal of the day, in the morning", "translation": ""}], "possibleAnswers": ["I usually have bread with cheese and a glass of milk.", "For breakfast I eat cereal with banana slices.", "I have toast and a boiled egg, and sometimes jam."]}, {"original": "Would you rather eat pizza or a big salad?", "paraphrased": "Which would you pick: pizza or a fresh salad?", "vocab": [{"word": "rather", "definition": "used to say what you prefer", "translation": ""}, {"word": "pick", "definition": "to choose one thing", "translation": ""}], "possibleAnswers": ["I would rather eat pizza. It is my favourite food.", "I pick a big salad in summer because it is fresh.", "Pizza, of course! But salad is healthy too."]}, {"original": "Have you ever tried food from another country?", "paraphrased": "Tell me about a dish from a different country.", "vocab": [{"word": "tried", "definition": "eaten something to see if you like it (past of 'try')", "translation": ""}, {"word": "country", "definition": "a place with its own people and government, like France or Japan", "translation": ""}], "possibleAnswers": ["Yes, I tried sushi from Japan. I liked the rice but not the fish.", "I ate pasta in Italy. It was the best food ever.", "We made tacos at home. They were spicy and fun."]}, {"original": "Is there a snack you like to eat between meals?", "paraphrased": "What do you enjoy eating when you feel a little hungry?", "vocab": [{"word": "snack", "definition": "a small amount of food you eat between main meals", "translation": ""}, {"word": "hungry", "definition": "wanting to eat food", "translation": ""}], "possibleAnswers": ["I like biscuits and a glass of milk in the afternoon.", "My favourite snack is popcorn when we watch a film.", "I eat an apple or some nuts after school."]}, {"original": "What is the strangest food you have ever eaten?", "paraphrased": "Tell me about an unusual food you tried.", "vocab": [{"word": "strangest", "definition": "the most unusual or surprising", "translation": ""}, {"word": "unusual", "definition": "not common; different from what you expect", "translation": ""}], "possibleAnswers": ["I ate olives. They were very salty and a little strange.", "I tried seaweed. It was not bad, but I would not eat it again.", "The strangest food was a very spicy soup at a market."]}, {"original": "Is there a food you do not like but your family loves?", "paraphrased": "Tell me about food your family enjoys that you dislike.", "vocab": [{"word": "food", "definition": "things we eat to live and stay healthy", "translation": ""}, {"word": "enjoys", "definition": "likes and has fun with", "translation": ""}], "possibleAnswers": ["My family loves broccoli, but I really do not like it.", "My dad loves very spicy food. For me it is too hot.", "My sister loves bananas, and I cannot eat them."]}, {"original": "Which drink do you like best with your dinner?", "paraphrased": "Which drink do you prefer when you eat your evening meal?", "vocab": [{"word": "drink", "definition": "a liquid you swallow, like water, milk or juice", "translation": ""}, {"word": "dinner", "definition": "the main evening meal", "translation": ""}], "possibleAnswers": ["I like water best. It is good for me.", "I drink apple juice with dinner. It is sweet.", "I like milk, but sometimes I have a fizzy drink at the weekend."]}, {"original": "If you could eat only one food forever, what would it be?", "paraphrased": "Which single food would you choose to eat every day?", "vocab": [{"word": "forever", "definition": "for all time; always", "translation": ""}, {"word": "single", "definition": "only one; not two or more", "translation": ""}], "possibleAnswers": ["I would choose pasta. I never get tired of it.", "Pizza forever! It has everything I like.", "I would pick strawberries, but only in summer."]}, {"original": "What food do you like to eat when it is cold outside?", "paraphrased": "Tell me about a warm food you enjoy in winter.", "vocab": [{"word": "cold", "definition": "having a low temperature; not warm", "translation": ""}, {"word": "warm", "definition": "a little hot; pleasant and not cold", "translation": ""}], "possibleAnswers": ["I love hot soup with bread on cold days.", "I like hot chocolate and pancakes when it is snowing.", "We eat warm stew and rice. It makes me feel cosy."]}]}, {"title": "Helping at Home (12 questions)", "slug": "helpathome", "level": "A1-A2", "questions": [{"original": "Would you rather help cook or help wash the dishes?", "paraphrased": "Do you prefer cooking or washing up?", "vocab": [{"word": "rather", "definition": "used to say which of two things you prefer", "translation": ""}, {"word": "wash", "definition": "to clean something with water and soap", "translation": ""}], "possibleAnswers": ["I would rather help cook. It smells nice and I can taste.", "I prefer washing the dishes. It is quick and my mum is happy.", "Cooking, because afterwards we eat something delicious."]}, {"original": "What chores do you do at home every week?", "paraphrased": "Tell me about the jobs you do regularly at home.", "vocab": [{"word": "chores", "definition": "small jobs you do at home, like cleaning or tidying", "translation": ""}, {"word": "regularly", "definition": "often; happening again and again", "translation": ""}], "possibleAnswers": ["I make my bed and put my clothes away every day.", "I take out the rubbish on Monday and Friday.", "I help set the table and I feed my pet."]}, {"original": "Is pocket money something you receive for helping at home?", "paraphrased": "Tell me if you receive money for the jobs you do.", "vocab": [{"word": "pocket money", "definition": "a small amount of money your parents give you", "translation": ""}, {"word": "receive", "definition": "to get something that someone gives you", "translation": ""}], "possibleAnswers": ["Yes, I get a little money when I clean my room.", "No, I help because I am part of the family.", "Sometimes my grandma gives me a coin for helping her."]}, {"original": "What is the easiest chore for you at home?", "paraphrased": "Which job at home do you find simple?", "vocab": [{"word": "easiest", "definition": "the one that needs the least effort", "translation": ""}, {"word": "simple", "definition": "easy to do; not difficult", "translation": ""}], "possibleAnswers": ["Watering the plants is easy and I like doing it.", "Putting my toys in the box is the easiest chore.", "I find it easy to fold my own clothes."]}, {"original": "Have you ever helped to cook a meal for your family?", "paraphrased": "Tell me about preparing a meal for the people you live with.", "vocab": [{"word": "cooked", "definition": "made food hot and ready to eat (past of 'cook')", "translation": ""}, {"word": "preparing", "definition": "making something ready before you use or eat it", "translation": ""}], "possibleAnswers": ["Yes, I helped my mum make a vegetable soup.", "I cooked rice and eggs by myself. It was a little burnt!", "I made a salad for everyone last Sunday."]}, {"original": "Who does the most work in your home?", "paraphrased": "Which person in your family has the biggest jobs?", "vocab": [{"word": "work", "definition": "the effort you use to do a job", "translation": ""}, {"word": "biggest", "definition": "the largest in size or amount", "translation": ""}], "possibleAnswers": ["My mum does the most work. She cooks and cleans every day.", "My dad works very hard in the garden.", "I think everyone helps the same, but my mum does a little more."]}, {"original": "Tell me which is worse: cleaning the bathroom or tidying the living room.", "paraphrased": "Which room would you choose to clean?", "vocab": [{"word": "clean", "definition": "to remove dirt so something is not dirty", "translation": ""}, {"word": "tidy", "definition": "to put things in order so a place looks neat", "translation": ""}], "possibleAnswers": ["I would rather tidy the living room. It is faster.", "Cleaning the bathroom is not fun, but it must be done.", "I choose the living room because the bathroom smells funny."]}, {"original": "How do you help your family at the weekend?", "paraphrased": "How do you help out on Saturday and Sunday?", "vocab": [{"word": "weekend", "definition": "Saturday and Sunday, when school is closed", "translation": ""}, {"word": "help out", "definition": "to do useful things for other people", "translation": ""}], "possibleAnswers": ["I help my dad in the garden and I water the flowers.", "On Saturday I clean my room and help with the shopping.", "I look after my little brother so my mum can rest."]}, {"original": "Is it important to help at home? Why do you think so?", "paraphrased": "Tell me why helping at home matters to you.", "vocab": [{"word": "important", "definition": "having great value; something we should do", "translation": ""}, {"word": "matters", "definition": "is important; has an effect", "translation": ""}], "possibleAnswers": ["Yes, because everyone in the family should do a little work.", "It is important because our home stays clean and nice.", "I think so, because it makes my mum happy and less tired."]}, {"original": "Is there a new chore you would like to learn to do?", "paraphrased": "Which household job would you like to try?", "vocab": [{"word": "chore", "definition": "a small regular job you do at home", "translation": ""}, {"word": "learn", "definition": "to get new knowledge or a skill by practising", "translation": ""}], "possibleAnswers": ["I would like to learn how to cook pasta with sauce.", "I want to learn how to use the washing machine.", "I would like to learn to fix small things, like a loose shelf."]}, {"original": "How do you feel after you help someone at home?", "paraphrased": "Tell me about your feelings when you help your family.", "vocab": [{"word": "feel", "definition": "to have an emotion, like happy or proud", "translation": ""}, {"word": "proud", "definition": "pleased with something you have done well", "translation": ""}], "possibleAnswers": ["I feel happy and proud. My mum always says thank you.", "It feels good because I know I did something useful.", "I am tired, but happy. Helping is good exercise too."]}, {"original": "If you were the teacher for one day, what would you teach your family?", "paraphrased": "What useful thing would you show your family how to do?", "vocab": [{"word": "teacher", "definition": "a person who helps others learn new things", "translation": ""}, {"word": "useful", "definition": "helpful; good for a purpose", "translation": ""}], "possibleAnswers": ["I would teach them how to fold a shirt quickly.", "I would teach them a fun dance, not a chore!", "I would show them how to make a healthy fruit salad."]}]}]}, {"category": "School and Friends", "topics": [{"title": "My School Day (12 questions)", "slug": "myschoolday", "level": "A1-A2", "questions": [{"original": "What time do you get up on a school morning?", "paraphrased": "Can you tell me what time you wake up on school days?", "vocab": [{"word": "morning", "definition": "the early part of the day, after you wake up", "translation": ""}, {"word": "get up", "definition": "to leave your bed and start your day", "translation": ""}], "possibleAnswers": ["I get up at seven o'clock on school days.", "I wake up early, at half past six, and have breakfast."]}, {"original": "How do you travel to school each morning?", "paraphrased": "Do you walk, or does someone drive you to school?", "vocab": [{"word": "travel", "definition": "to go from one place to another", "translation": ""}, {"word": "morning", "definition": "the first part of the day", "translation": ""}], "possibleAnswers": ["I walk to school with my neighbour.", "My mum drives me to school in her car."]}, {"original": "What is the first lesson you have on Monday?", "paraphrased": "Which subject do you start with on Monday morning?", "vocab": [{"word": "lesson", "definition": "a time when you learn something at school", "translation": ""}, {"word": "first", "definition": "number one; before all the others", "translation": ""}], "possibleAnswers": ["The first lesson on Monday is English.", "We start with maths on Monday morning."]}, {"original": "Do you eat lunch at school or at home?", "paraphrased": "Is your lunch at school, or do you go home to eat?", "vocab": [{"word": "lunch", "definition": "the meal you eat in the middle of the day", "translation": ""}, {"word": "school", "definition": "the place where you go to learn", "translation": ""}], "possibleAnswers": ["I eat lunch at school with my friends.", "I go home for lunch because it is close."]}, {"original": "Who do you sit next to in class?", "paraphrased": "Can you tell me the name of the person beside your desk?", "vocab": [{"word": "sit", "definition": "to rest on a chair", "translation": ""}, {"word": "class", "definition": "a group of students who learn together", "translation": ""}], "possibleAnswers": ["I sit next to my friend Sam.", "My cousin sits next to me in class."]}, {"original": "What do you usually have for lunch at school?", "paraphrased": "Tell me about the food you eat at school for lunch.", "vocab": [{"word": "usually", "definition": "most of the time; what you do often", "translation": ""}, {"word": "food", "definition": "things you eat, like bread or rice", "translation": ""}], "possibleAnswers": ["I usually have a sandwich and an apple.", "We have rice and chicken at school on Fridays."]}, {"original": "Is your school bag heavy in the morning?", "paraphrased": "Do you carry many books in your bag for school?", "vocab": [{"word": "bag", "definition": "a thing you carry your books in", "translation": ""}, {"word": "heavy", "definition": "hard to lift because it weighs a lot", "translation": ""}], "possibleAnswers": ["Yes, my bag is heavy because I have many books.", "No, I only carry a few books and my lunch."]}, {"original": "Which part of the school day do you like best?", "paraphrased": "Do you prefer the morning lessons or the afternoon ones?", "vocab": [{"word": "part", "definition": "one piece of something bigger", "translation": ""}, {"word": "best", "definition": "the one you like most", "translation": ""}], "possibleAnswers": ["I like break time best because I can play outside.", "The afternoon is my favourite part of the day."]}, {"original": "Can you tell me what your classroom looks like?", "paraphrased": "What do you see when you look around your classroom?", "vocab": [{"word": "classroom", "definition": "the room where your class has lessons", "translation": ""}, {"word": "look", "definition": "to use your eyes to see something", "translation": ""}], "possibleAnswers": ["My classroom is big, with colourful posters on the walls.", "There are twenty desks and a large window in my room."]}, {"original": "Does your mum or dad drive you to school?", "paraphrased": "Who takes you to school in the car?", "vocab": [{"word": "drive", "definition": "to take someone somewhere in a car", "translation": ""}, {"word": "dad", "definition": "another word for father", "translation": ""}], "possibleAnswers": ["My mum drives me to school every day.", "No, I walk with my older brother."]}, {"original": "Would you rather play outside or read after school?", "paraphrased": "After school, do you prefer playing or reading a book?", "vocab": [{"word": "rather", "definition": "used to say what you prefer", "translation": ""}, {"word": "outside", "definition": "not inside a building; in the open air", "translation": ""}], "possibleAnswers": ["I would rather play outside with my friends.", "I like reading a comic after school."]}, {"original": "Tell me about something fun you did at school this week.", "paraphrased": "What fun thing happened at school in the last few days?", "vocab": [{"word": "fun", "definition": "something you enjoy; a happy time", "translation": ""}, {"word": "week", "definition": "seven days, from Monday to Sunday", "translation": ""}], "possibleAnswers": ["We played a great game of football on Wednesday.", "My class did a fun science experiment on Friday."]}]}, {"title": "My Teachers (12 questions)", "slug": "myteachers", "level": "A1-A2", "questions": [{"original": "What is your teacher's name, and what do they teach?", "paraphrased": "Can you tell me your teacher's name and their subject?", "vocab": [{"word": "teacher", "definition": "a person who helps you learn at school", "translation": ""}, {"word": "teach", "definition": "to help someone learn something", "translation": ""}], "possibleAnswers": ["My teacher is Mrs Brown, and she teaches us English.", "Mr Ali is my teacher, and he teaches maths."]}, {"original": "Do you think your teacher is kind and funny?", "paraphrased": "Is your teacher nice and fun to be around?", "vocab": [{"word": "kind", "definition": "friendly and caring; nice to other people", "translation": ""}, {"word": "funny", "definition": "making you laugh; amusing", "translation": ""}], "possibleAnswers": ["Yes, my teacher is very kind and tells funny jokes.", "She is kind, but she is quiet, not funny."]}, {"original": "Which teacher do you like the most at school?", "paraphrased": "Who is your favourite teacher, and why do you like them?", "vocab": [{"word": "favourite", "definition": "the person or thing you like most", "translation": ""}, {"word": "school", "definition": "the place where you learn", "translation": ""}], "possibleAnswers": ["I like my art teacher most because we draw fun pictures.", "My favourite teacher is Mr John, the music teacher."]}, {"original": "Can you tell me about a teacher who helps you?", "paraphrased": "Which teacher do you go to when you need help?", "vocab": [{"word": "help", "definition": "to make something easier for someone", "translation": ""}, {"word": "need", "definition": "when you must have something", "translation": ""}], "possibleAnswers": ["My English teacher helps me with my reading.", "I ask my science teacher when I do not understand."]}, {"original": "How does your teacher make your lessons fun?", "paraphrased": "What does your teacher do to make class enjoyable?", "vocab": [{"word": "lesson", "definition": "a time when you learn at school", "translation": ""}, {"word": "fun", "definition": "enjoyable; making you happy", "translation": ""}], "possibleAnswers": ["She plays games with us before the lesson starts.", "He tells us funny stories about his life."]}, {"original": "What do you do when your teacher asks a question?", "paraphrased": "Do you put your hand up when the teacher asks something?", "vocab": [{"word": "ask", "definition": "to say a question and want an answer", "translation": ""}, {"word": "question", "definition": "words that ask for information", "translation": ""}], "possibleAnswers": ["I put my hand up and try to answer.", "I listen carefully and wait for the teacher to choose me."]}, {"original": "Is there a teacher you want to thank?", "paraphrased": "Is there a teacher who helped you a lot this year?", "vocab": [{"word": "thank", "definition": "to tell someone you are grateful", "translation": ""}, {"word": "year", "definition": "twelve months, like a school year", "translation": ""}], "possibleAnswers": ["Yes, I want to thank my teacher for her patience.", "I would thank my coach for helping me run faster."]}, {"original": "Tell me about something nice your teacher said to you.", "paraphrased": "What kind words did your teacher say to you recently?", "vocab": [{"word": "nice", "definition": "kind and pleasant; making you feel good", "translation": ""}, {"word": "said", "definition": "the past of 'say'; to speak words", "translation": ""}], "possibleAnswers": ["She said my drawing was very creative.", "My teacher told me I am good at maths."]}, {"original": "Does your teacher read stories to the class?", "paraphrased": "Do you have story time with your teacher at school?", "vocab": [{"word": "story", "definition": "a tale about people and events, often fun", "translation": ""}, {"word": "read", "definition": "to look at words and understand them", "translation": ""}], "possibleAnswers": ["Yes, we read a story together every Friday.", "No, but our teacher sometimes tells us stories."]}, {"original": "Who is the funniest teacher at your school?", "paraphrased": "Which teacher makes your class laugh the most?", "vocab": [{"word": "funniest", "definition": "the most amusing; making you laugh the most", "translation": ""}, {"word": "school", "definition": "the place where you learn", "translation": ""}], "possibleAnswers": ["Mr Lee is the funniest; he does funny voices.", "Our music teacher is very funny and kind."]}, {"original": "Would you rather have a funny teacher or a quiet one?", "paraphrased": "Which do you prefer: a teacher who jokes, or a calm one?", "vocab": [{"word": "rather", "definition": "used to say what you prefer", "translation": ""}, {"word": "quiet", "definition": "not loud; making little noise", "translation": ""}], "possibleAnswers": ["I would rather have a funny teacher because class is fun.", "I prefer a quiet teacher because it is easier to think."]}, {"original": "What subject does your favourite teacher teach best?", "paraphrased": "Which lesson does your favourite teacher do really well?", "vocab": [{"word": "subject", "definition": "a thing you learn at school, like maths or art", "translation": ""}, {"word": "teach", "definition": "to help someone learn", "translation": ""}], "possibleAnswers": ["My favourite teacher teaches science really well.", "She is great at teaching us to read English."]}]}, {"title": "My Best Friend (12 questions)", "slug": "mybestfriend", "level": "A1-A2", "questions": [{"original": "Who is your best friend, and how old are they?", "paraphrased": "What is your best friend's name, and what age are they?", "vocab": [{"word": "friend", "definition": "a person you like and spend time with", "translation": ""}, {"word": "old", "definition": "how many years a person has lived", "translation": ""}], "possibleAnswers": ["My best friend is Lina, and she is ten years old.", "His name is Tom, and he is eleven."]}, {"original": "Which games do you and your best friend play together?", "paraphrased": "What do you and your best friend enjoy playing?", "vocab": [{"word": "game", "definition": "an activity you play for fun", "translation": ""}, {"word": "together", "definition": "with another person; not alone", "translation": ""}], "possibleAnswers": ["We play football and card games together.", "We like playing hide and seek in the park."]}, {"original": "Where did you first meet your best friend?", "paraphrased": "Can you remember the place where you met your friend?", "vocab": [{"word": "meet", "definition": "to see someone for the first time", "translation": ""}, {"word": "first", "definition": "before everything else; number one", "translation": ""}], "possibleAnswers": ["We first met in the school playground.", "I met my best friend at my old school."]}, {"original": "Do you and your friend like the same games?", "paraphrased": "Are your favourite games the same as your friend's?", "vocab": [{"word": "same", "definition": "alike; not different", "translation": ""}, {"word": "like", "definition": "to enjoy something", "translation": ""}], "possibleAnswers": ["Yes, we both love playing football.", "No, I like drawing and she likes running."]}, {"original": "Can you tell me one kind thing your friend did?", "paraphrased": "What is something nice your friend has done for you?", "vocab": [{"word": "kind", "definition": "friendly and helpful to others", "translation": ""}, {"word": "thing", "definition": "an object or an action; something", "translation": ""}], "possibleAnswers": ["She helped me with my homework last week.", "He shared his lunch with me when I forgot mine."]}, {"original": "What makes your best friend laugh a lot?", "paraphrased": "What funny thing does your friend always enjoy?", "vocab": [{"word": "laugh", "definition": "to make a happy sound when something is funny", "translation": ""}, {"word": "funny", "definition": "making you laugh", "translation": ""}], "possibleAnswers": ["My friend laughs a lot at my silly drawings.", "He laughs when I tell jokes at lunch."]}, {"original": "Is your best friend in the same class as you?", "paraphrased": "Do you and your best friend share a classroom?", "vocab": [{"word": "same", "definition": "alike; not different", "translation": ""}, {"word": "class", "definition": "a group of students who learn together", "translation": ""}], "possibleAnswers": ["Yes, we are in the same class this year.", "No, she is in Class 4 and I am in Class 5."]}, {"original": "Tell me about a fun day you had with your friend.", "paraphrased": "What fun thing did you do together recently?", "vocab": [{"word": "fun", "definition": "enjoyable; making you happy", "translation": ""}, {"word": "day", "definition": "the time from morning to night, 24 hours", "translation": ""}], "possibleAnswers": ["We went to the park and played on the swings all day.", "We had a fun day making a cake at her house."]}, {"original": "What do you talk about with your best friend?", "paraphrased": "Which things do you and your friend chat about?", "vocab": [{"word": "talk", "definition": "to speak with someone; to chat", "translation": ""}, {"word": "chat", "definition": "to talk in a friendly, relaxed way", "translation": ""}], "possibleAnswers": ["We talk about football and our favourite games.", "We chat about school and our families."]}, {"original": "Would you rather play with your friend or your cousin?", "paraphrased": "Do you prefer spending time with your friend or your cousin?", "vocab": [{"word": "rather", "definition": "used to say what you prefer", "translation": ""}, {"word": "cousin", "definition": "the child of your aunt or uncle", "translation": ""}], "possibleAnswers": ["I would rather play with my best friend.", "I like playing with my cousin at the weekend."]}, {"original": "Does your best friend ever help you with school work?", "paraphrased": "Do you and your friend study together sometimes?", "vocab": [{"word": "help", "definition": "to make something easier for someone", "translation": ""}, {"word": "work", "definition": "tasks you do; school tasks", "translation": ""}], "possibleAnswers": ["Yes, she helps me with maths after school.", "We study together before our tests."]}, {"original": "How long have you been friends with your best friend?", "paraphrased": "For how many years have you and your friend known each other?", "vocab": [{"word": "long", "definition": "a great amount of time", "translation": ""}, {"word": "friend", "definition": "a person you like and trust", "translation": ""}], "possibleAnswers": ["We have been friends for three years.", "We have known each other since we were five."]}]}, {"title": "Playing Together (12 questions)", "slug": "playingtogether", "level": "A1-A2", "questions": [{"original": "What games do you like to play at break time?", "paraphrased": "Which games do you enjoy when school is on a break?", "vocab": [{"word": "game", "definition": "an activity you play for fun", "translation": ""}, {"word": "break", "definition": "a short rest time between lessons", "translation": ""}], "possibleAnswers": ["I like playing football at break time.", "We play tag and hide and seek outside."]}, {"original": "Do you prefer playing inside or outside at school?", "paraphrased": "Would you rather play indoors or in the playground?", "vocab": [{"word": "prefer", "definition": "to like one thing more than another", "translation": ""}, {"word": "inside", "definition": "within a building, not outdoors", "translation": ""}], "possibleAnswers": ["I prefer playing outside because I can run.", "I like playing inside when the weather is bad."]}, {"original": "Who do you usually play with at break time?", "paraphrased": "Which friends join your games during break?", "vocab": [{"word": "usually", "definition": "most of the time; what you do often", "translation": ""}, {"word": "break", "definition": "a short rest time between lessons", "translation": ""}], "possibleAnswers": ["I usually play with my best friend and his brother.", "I play with the children from my class."]}, {"original": "Can you teach me a game you play with friends?", "paraphrased": "Would you show me how to play one of your games?", "vocab": [{"word": "teach", "definition": "to show someone how to do something", "translation": ""}, {"word": "friend", "definition": "a person you like and spend time with", "translation": ""}], "possibleAnswers": ["Yes, I can teach you to play musical statues.", "I will show you how to play four square."]}, {"original": "What is your favourite game to play in the playground?", "paraphrased": "Which playground game do you enjoy the most?", "vocab": [{"word": "favourite", "definition": "the one you like most", "translation": ""}, {"word": "playground", "definition": "an outdoor area at school with space to play", "translation": ""}], "possibleAnswers": ["My favourite game is football in the playground.", "I love playing on the climbing frame."]}, {"original": "How do you choose teams when you play a game?", "paraphrased": "What do you do to pick teams for a game?", "vocab": [{"word": "choose", "definition": "to pick one thing from many", "translation": ""}, {"word": "team", "definition": "a group of players who play together", "translation": ""}], "possibleAnswers": ["We count one, two and pick captains.", "The two captains choose players one by one."]}, {"original": "Would you rather play a quiet game or a running game?", "paraphrased": "Do you prefer calm games or games where you run?", "vocab": [{"word": "rather", "definition": "used to say what you prefer", "translation": ""}, {"word": "quiet", "definition": "not loud; calm", "translation": ""}], "possibleAnswers": ["I would rather play a running game like tag.", "I prefer a quiet game like cards."]}, {"original": "What do you do when a friend wants a different game?", "paraphrased": "How do you decide which game to play together?", "vocab": [{"word": "different", "definition": "not the same; another one", "translation": ""}, {"word": "decide", "definition": "to choose after thinking", "translation": ""}], "possibleAnswers": ["We take turns and play each game for a while.", "I usually agree and try the new game."]}, {"original": "Is there a game you always play with your class?", "paraphrased": "Which game does your class play every break time?", "vocab": [{"word": "always", "definition": "every time; all the time", "translation": ""}, {"word": "class", "definition": "a group of students who learn together", "translation": ""}], "possibleAnswers": ["Yes, we always play football together.", "We always play a game called dodgeball."]}, {"original": "Tell me about a game you played yesterday.", "paraphrased": "What game did you enjoy yesterday?", "vocab": [{"word": "game", "definition": "an activity you play for fun", "translation": ""}, {"word": "yesterday", "definition": "the day before today", "translation": ""}], "possibleAnswers": ["Yesterday we played a fun game of rounders.", "I played football with my friends yesterday."]}, {"original": "Where do you play games with your friends after school?", "paraphrased": "Which place do you go to play after school?", "vocab": [{"word": "where", "definition": "in or to which place", "translation": ""}, {"word": "after", "definition": "later than something; when school ends", "translation": ""}], "possibleAnswers": ["We play in the park near my house.", "I play games at my friend's house after school."]}, {"original": "Which is more fun, playing alone or with friends?", "paraphrased": "Do you enjoy playing by yourself or with others more?", "vocab": [{"word": "alone", "definition": "by yourself; without other people", "translation": ""}, {"word": "fun", "definition": "enjoyable; making you happy", "translation": ""}], "possibleAnswers": ["Playing with friends is more fun for me.", "I like playing alone sometimes, but friends are better."]}]}, {"title": "My Favourite Subject (12 questions)", "slug": "myschoolsubjects", "level": "A1-A2", "questions": [{"original": "What is your favourite subject at school, and why?", "paraphrased": "Which school subject do you enjoy the most, and what makes it fun?", "vocab": [{"word": "favourite", "definition": "the one you like most", "translation": ""}, {"word": "subject", "definition": "a thing you learn at school, like maths", "translation": ""}], "possibleAnswers": ["My favourite subject is art because I love drawing.", "I like science best because we do fun experiments."]}, {"original": "Which subject do you like the least at school?", "paraphrased": "Which lesson do you enjoy the least, and why?", "vocab": [{"word": "least", "definition": "the smallest amount; not as much as others", "translation": ""}, {"word": "school", "definition": "the place where you learn", "translation": ""}], "possibleAnswers": ["I like history least because it has many dates.", "I enjoy maths the least, but I am getting better."]}, {"original": "Do you enjoy reading books in English class?", "paraphrased": "Is reading books something you like in English lessons?", "vocab": [{"word": "enjoy", "definition": "to like something and have fun doing it", "translation": ""}, {"word": "read", "definition": "to look at words and understand them", "translation": ""}], "possibleAnswers": ["Yes, I enjoy reading stories in English class.", "I like reading books, especially about animals."]}, {"original": "Can you tell me what you learn in science?", "paraphrased": "What topics do you study in your science lessons?", "vocab": [{"word": "learn", "definition": "to get new knowledge or skills", "translation": ""}, {"word": "science", "definition": "the study of nature, plants and how things work", "translation": ""}], "possibleAnswers": ["We learn about plants, animals and the weather.", "In science we learn how things grow and move."]}, {"original": "How does your art teacher help you draw better?", "paraphrased": "What does your art teacher do to improve your drawing?", "vocab": [{"word": "draw", "definition": "to make a picture with a pencil or pen", "translation": ""}, {"word": "better", "definition": "improving; getting higher in skill", "translation": ""}], "possibleAnswers": ["She shows me how to use colours and shapes.", "My art teacher helps me draw people more easily."]}, {"original": "Is maths fun for you, or is it difficult?", "paraphrased": "Do you find maths enjoyable, or hard work?", "vocab": [{"word": "maths", "definition": "the study of numbers and sums", "translation": ""}, {"word": "difficult", "definition": "hard; not easy", "translation": ""}], "possibleAnswers": ["Maths is fun for me because I like numbers.", "It is a little difficult, but I enjoy it now."]}, {"original": "Tell me about a fun lesson you had this week.", "paraphrased": "What enjoyable lesson did you have in the last few days?", "vocab": [{"word": "lesson", "definition": "a time when you learn at school", "translation": ""}, {"word": "fun", "definition": "enjoyable; making you happy", "translation": ""}], "possibleAnswers": ["We had a fun music lesson and played drums.", "Our science lesson was fun because we made a volcano."]}, {"original": "Who is the teacher for your favourite subject?", "paraphrased": "Which teacher teaches the subject you like best?", "vocab": [{"word": "teacher", "definition": "a person who helps you learn at school", "translation": ""}, {"word": "subject", "definition": "a thing you learn at school, like art", "translation": ""}], "possibleAnswers": ["Mrs Hill is the teacher for my favourite subject, art.", "Mr Sami teaches music, my favourite subject."]}, {"original": "Would you rather do art or music at school?", "paraphrased": "Which do you prefer: art lessons or music lessons?", "vocab": [{"word": "rather", "definition": "used to say what you prefer", "translation": ""}, {"word": "music", "definition": "songs and sounds you play or sing", "translation": ""}], "possibleAnswers": ["I would rather do art because I love to paint.", "I prefer music because I enjoy singing."]}, {"original": "What do you use in your favourite lesson?", "paraphrased": "Which tools or things do you need for that lesson?", "vocab": [{"word": "use", "definition": "to do something with an object", "translation": ""}, {"word": "need", "definition": "to require something; to have to have it", "translation": ""}], "possibleAnswers": ["I use paper, pencils and paint in art.", "We use books and pencils in English."]}, {"original": "Does your school have a subject you wish for?", "paraphrased": "Is there a subject you would like your school to teach?", "vocab": [{"word": "school", "definition": "the place where you learn", "translation": ""}, {"word": "wish", "definition": "to want something that you do not have", "translation": ""}], "possibleAnswers": ["Yes, I wish my school had a drama club.", "I wish we could learn about computers more."]}, {"original": "Where do you sit in your favourite lesson?", "paraphrased": "Do you have a special seat in your favourite class?", "vocab": [{"word": "sit", "definition": "to rest on a chair", "translation": ""}, {"word": "lesson", "definition": "a time when you learn at school", "translation": ""}], "possibleAnswers": ["I sit near the front so I can see the board.", "I sit next to my friend at the back."]}]}]}, {"category": "Fun and Free Time", "topics": [{"title": "Games and Sports (12 questions)", "slug": "gamesandsports", "level": "A1-A2", "questions": [{"original": "What is your favourite game to play with your friends?", "paraphrased": "Which game do you enjoy most when you play with friends?", "vocab": [{"word": "favourite", "definition": "the one you like best", "translation": ""}, {"word": "friends", "definition": "people you like to spend time with", "translation": ""}], "possibleAnswers": ["I love playing football with my friends after school.", "My favourite is hide and seek. It is so much fun!", "I like board games, especially ones we can play together."]}, {"original": "Do you like playing football, and why is that?", "paraphrased": "Is football a sport you enjoy? Tell me why.", "vocab": [{"word": "football", "definition": "a game where you kick a ball into a goal", "translation": ""}, {"word": "enjoy", "definition": "to like something very much", "translation": ""}], "possibleAnswers": ["Yes, I love it! I play with my friends every weekend.", "Not really. I prefer swimming because it is cool in summer.", "Sometimes. I like watching it more than playing it."]}, {"original": "Which sport do you like watching on television?", "paraphrased": "What sport do you enjoy seeing on TV?", "vocab": [{"word": "sport", "definition": "a game or activity where you move your body", "translation": ""}, {"word": "television", "definition": "the machine with a screen that shows programmes", "translation": ""}], "possibleAnswers": ["I like watching football. The players are so fast!", "I enjoy swimming competitions. The water looks so blue.", "I do not watch much sport. I like cartoons more."]}, {"original": "Would you rather play a board game or a computer game?", "paraphrased": "Do you prefer board games or games on a screen?", "vocab": [{"word": "board game", "definition": "a game you play on a table with pieces and cards", "translation": ""}, {"word": "prefer", "definition": "to like one thing more than another", "translation": ""}], "possibleAnswers": ["I would rather play a board game with my family.", "Computer games, of course! I love the colours and sounds.", "Both are fun, but I like board games on rainy days."]}, {"original": "What new game would you like to learn this year?", "paraphrased": "Which game do you want to try learning soon?", "vocab": [{"word": "learn", "definition": "to get better at something by practising", "translation": ""}, {"word": "year", "definition": "twelve months, from January to December", "translation": ""}], "possibleAnswers": ["I want to learn chess. It looks interesting.", "I would like to try volleyball at school.", "I want to learn a new card game with my brother."]}, {"original": "How often do you play outside after school?", "paraphrased": "Do you play outdoors most days after class?", "vocab": [{"word": "often", "definition": "many times, or most of the time", "translation": ""}, {"word": "outside", "definition": "not inside a building; in the open air", "translation": ""}], "possibleAnswers": ["Every day! I play football with my neighbours.", "Only on weekends. I am very busy on school days.", "Almost every day, when the weather is nice."]}, {"original": "Who do you like to play games with at home?", "paraphrased": "Which person do you enjoy playing with at home?", "vocab": [{"word": "play", "definition": "to do something fun, like a game", "translation": ""}, {"word": "home", "definition": "the place where you live with your family", "translation": ""}], "possibleAnswers": ["I play with my little sister. We love card games.", "My best friend comes to my house and we play.", "I like playing with my dad. He makes me laugh."]}, {"original": "Tell me about a fun game you played last week.", "paraphrased": "What game did you enjoy playing recently?", "vocab": [{"word": "fun", "definition": "something that makes you happy and laugh", "translation": ""}, {"word": "week", "definition": "seven days, from Monday to Sunday", "translation": ""}], "possibleAnswers": ["We played a great game at the park. Everyone laughed.", "I played a board game with my family. It was exciting!", "My friend taught me a new game. I loved it."]}, {"original": "Is there a sport you want to try but have not tried yet?", "paraphrased": "Which sport would you like to try for the first time?", "vocab": [{"word": "try", "definition": "to do something new to see if you like it", "translation": ""}, {"word": "yet", "definition": "used to say something has not happened so far", "translation": ""}], "possibleAnswers": ["Yes, I want to try tennis. It looks fun!", "I would like to try ice skating in winter.", "I want to try basketball. The hoops look high!"]}, {"original": "What is the best thing about playing team games?", "paraphrased": "Why do you enjoy games played with a team?", "vocab": [{"word": "best", "definition": "the most good; better than all the others", "translation": ""}, {"word": "team", "definition": "a group of people who play together", "translation": ""}], "possibleAnswers": ["You make new friends and laugh together.", "I love working with my friends to win.", "It feels great when everyone helps each other."]}, {"original": "Do you prefer indoor games or outdoor games?", "paraphrased": "Do you like games inside the house or in the garden more?", "vocab": [{"word": "indoor", "definition": "inside a building", "translation": ""}, {"word": "outdoor", "definition": "outside, in the open air", "translation": ""}], "possibleAnswers": ["I prefer outdoor games. I love running in the sun.", "Indoor games, because they are warm and cosy.", "It depends on the weather, but I like both."]}, {"original": "If you could invent a new game, what would it be called?", "paraphrased": "What name would you give to a game you made?", "vocab": [{"word": "invent", "definition": "to make or think of something new", "translation": ""}, {"word": "called", "definition": "to have a particular name", "translation": ""}], "possibleAnswers": ["I would call it Super Ball. It would be very fast!", "It would be called Rainbow Run. I love rainbows.", "I would call it Happy Jump. Everyone would smile."]}]}, {"title": "Music, Films and TV (12 questions)", "slug": "musicfilmsandtv", "level": "A1-A2", "questions": [{"original": "What music do you like to listen to after school?", "paraphrased": "Which songs do you enjoy hearing when school ends?", "vocab": [{"word": "music", "definition": "sounds and songs that you listen to", "translation": ""}, {"word": "listen", "definition": "to pay attention to a sound", "translation": ""}], "possibleAnswers": ["I like pop music. It makes me want to dance!", "I listen to calm songs after a busy day.", "I enjoy music in my language and English songs too."]}, {"original": "Who is your favourite singer or music group?", "paraphrased": "Which person or group makes your favourite songs?", "vocab": [{"word": "singer", "definition": "a person who sings songs", "translation": ""}, {"word": "group", "definition": "a few people who make music together", "translation": ""}], "possibleAnswers": ["My favourite singer is Adele. Her voice is beautiful.", "I love a band called BTS. Their songs are fun.", "I like my cousin! She sings very well."]}, {"original": "Which cartoon do you enjoy watching the most?", "paraphrased": "What is your favourite cartoon on TV?", "vocab": [{"word": "cartoon", "definition": "a funny film with drawings, not real people", "translation": ""}, {"word": "watch", "definition": "to look at something, like a film", "translation": ""}], "possibleAnswers": ["I love watching cartoons after school.", "Yes! My favourite is about a clever cat.", "I like cartoons with animals and jokes."]}, {"original": "What is the last film you watched with your family?", "paraphrased": "Which movie did you see recently with your family?", "vocab": [{"word": "film", "definition": "a story you watch on a screen", "translation": ""}, {"word": "family", "definition": "the people you live with who love you", "translation": ""}], "possibleAnswers": ["We watched a funny film about a dog. We all laughed.", "The last film was about space. It was amazing!", "We saw a cartoon film at the cinema last weekend."]}, {"original": "Would you rather watch a funny film or a film about animals?", "paraphrased": "Do you prefer comedy films or films with animals?", "vocab": [{"word": "funny", "definition": "something that makes you laugh", "translation": ""}, {"word": "animal", "definition": "a living creature like a dog or a bird", "translation": ""}], "possibleAnswers": ["A funny film, please! I love to laugh.", "I would rather watch a film about animals. I love them!", "Both are great, but animals make me happy."]}, {"original": "How do you feel when you listen to your favourite song?", "paraphrased": "What happens inside you when your best-loved song plays?", "vocab": [{"word": "feel", "definition": "to have an emotion, like happy or sad", "translation": ""}, {"word": "song", "definition": "a short piece of music with words", "translation": ""}], "possibleAnswers": ["I feel happy and I start to dance!", "I feel calm, like everything is okay.", "It makes me smile and sing along."]}, {"original": "Tell me about a TV programme you enjoy watching.", "paraphrased": "Which show on television do you like?", "vocab": [{"word": "programme", "definition": "a show on television", "translation": ""}, {"word": "enjoy", "definition": "to like something a lot", "translation": ""}], "possibleAnswers": ["I enjoy a programme about wild animals.", "I like a funny programme with a silly dog.", "My favourite programme is about cooking for kids."]}, {"original": "Do you enjoy singing songs with your friends?", "paraphrased": "Is singing something you like to do?", "vocab": [{"word": "singing", "definition": "making music with your voice", "translation": ""}, {"word": "friend", "definition": "a person you like and have fun with", "translation": ""}], "possibleAnswers": ["Yes, I love singing in the school choir.", "I like singing in the shower, but not at school!", "Sometimes. I sing with my best friend at break."]}, {"original": "What kind of music do you like when you are happy?", "paraphrased": "Which music matches your happy mood?", "vocab": [{"word": "kind", "definition": "a type or sort of something", "translation": ""}, {"word": "happy", "definition": "feeling good and smiling", "translation": ""}], "possibleAnswers": ["I like fast, happy songs when I am cheerful.", "Pop music, because it is bright and fun.", "I like songs I can dance to."]}, {"original": "Which film character do you like the most?", "paraphrased": "Who is your favourite person in a movie?", "vocab": [{"word": "character", "definition": "a person or animal in a story or film", "translation": ""}, {"word": "most", "definition": "more than any other", "translation": ""}], "possibleAnswers": ["I like the funny mouse in the cartoon.", "My favourite character is a brave girl with magic.", "I love the kind robot in the space film."]}, {"original": "If you could make a film, what would it be about?", "paraphrased": "What story would you put in a film you made?", "vocab": [{"word": "make", "definition": "to create or produce something", "translation": ""}, {"word": "story", "definition": "a tale with people, places and events", "translation": ""}], "possibleAnswers": ["It would be about a cat who flies a balloon.", "A film about my school and my funny friends.", "It would be an adventure in a magical forest."]}, {"original": "What is a song you like to sing with your friends?", "paraphrased": "Which song do you and your friends enjoy singing?", "vocab": [{"word": "song", "definition": "music with words that people sing", "translation": ""}, {"word": "together", "definition": "with other people, not alone", "translation": ""}], "possibleAnswers": ["We love singing the song about the rainbow.", "We sing a funny song at birthday parties.", "We like the song we learned in music class."]}]}, {"title": "Books and Comics (12 questions)", "slug": "booksandcomics", "level": "A1-A2", "questions": [{"original": "Do you enjoy reading books in your free time?", "paraphrased": "Is reading something you like when school is over?", "vocab": [{"word": "enjoy", "definition": "to like doing something", "translation": ""}, {"word": "free time", "definition": "time when you are not working or at school", "translation": ""}], "possibleAnswers": ["Yes, I read every evening before bed.", "I enjoy reading, but only funny books.", "Not much. I prefer playing games."]}, {"original": "Where do you like reading: in bed or at your desk?", "paraphrased": "Do you prefer reading in bed or at a table?", "vocab": [{"word": "bed", "definition": "the soft place where you sleep", "translation": ""}, {"word": "desk", "definition": "a table where you sit to work or study", "translation": ""}], "possibleAnswers": ["I like reading in bed. It is warm and cosy.", "At my desk, so I can write notes.", "I read on the sofa with my cat."]}, {"original": "What is the last book you read at school?", "paraphrased": "Which book did your class read most recently?", "vocab": [{"word": "last", "definition": "the most recent one; the one before this", "translation": ""}, {"word": "class", "definition": "the group of students and teacher at school", "translation": ""}], "possibleAnswers": ["We read a book about a little bear.", "The last book was a story about the sea.", "We are reading a funny book about a school trip."]}, {"original": "Who is your favourite character in a story?", "paraphrased": "Which story person do you like the most?", "vocab": [{"word": "character", "definition": "a person or animal in a story", "translation": ""}, {"word": "story", "definition": "a tale with a beginning and an end", "translation": ""}], "possibleAnswers": ["I like the clever fox in the story.", "My favourite is a girl who can talk to birds.", "I love the friendly dragon. He is funny."]}, {"original": "Would you rather read a comic or a storybook?", "paraphrased": "Do you prefer comics or books with more words?", "vocab": [{"word": "comic", "definition": "a story told in pictures and speech bubbles", "translation": ""}, {"word": "storybook", "definition": "a book with a story, often with pictures", "translation": ""}], "possibleAnswers": ["I would rather read a comic. The pictures are fun!", "A storybook, because I like long adventures.", "Comics, because they are quick and funny."]}, {"original": "How many books do you read in one month?", "paraphrased": "What is your number of books each month?", "vocab": [{"word": "many", "definition": "a large number of something", "translation": ""}, {"word": "month", "definition": "one of the twelve parts of a year", "translation": ""}], "possibleAnswers": ["I read about two or three books a month.", "Only one. I am a slow reader.", "Four or five! I love reading before bed."]}, {"original": "Tell me about a book that made you laugh.", "paraphrased": "Which book was funny for you?", "vocab": [{"word": "laugh", "definition": "to make a happy sound when something is funny", "translation": ""}, {"word": "funny", "definition": "making you smile or laugh", "translation": ""}], "possibleAnswers": ["A book about a silly dog made me laugh.", "The story of the messy boy was very funny.", "My comic about a cat made me laugh a lot."]}, {"original": "Are there pictures or lots of words in your favourite book?", "paraphrased": "Does your favourite book have pictures or many words?", "vocab": [{"word": "picture", "definition": "a drawing or photo in a book", "translation": ""}, {"word": "word", "definition": "a single piece of language, like 'cat' or 'run'", "translation": ""}], "possibleAnswers": ["There are lots of words, but some pictures too.", "Mostly pictures! It is a comic.", "It has big words and colourful pictures."]}, {"original": "If you could meet a character from a book, who would you choose?", "paraphrased": "Which story person would you like to meet in real life?", "vocab": [{"word": "meet", "definition": "to see and talk to someone", "translation": ""}, {"word": "choose", "definition": "to pick one thing from many", "translation": ""}], "possibleAnswers": ["I would choose the brave mouse from my comic.", "I want to meet the girl who lives in a tree.", "I would meet the funny pirate from the story."]}, {"original": "What is your favourite comic strip or magazine?", "paraphrased": "Which comic or magazine do you like best?", "vocab": [{"word": "comic strip", "definition": "a short comic, often in a newspaper", "translation": ""}, {"word": "magazine", "definition": "a book of stories and pictures that comes every week or month", "translation": ""}], "possibleAnswers": ["I like a magazine about animals and nature.", "My favourite comic strip is about a clever dog.", "I enjoy a science magazine for kids."]}, {"original": "Do you like reading before you go to sleep?", "paraphrased": "Is a bedtime book part of your evening?", "vocab": [{"word": "read", "definition": "to look at words and understand them", "translation": ""}, {"word": "sleep", "definition": "the rest your body needs at night", "translation": ""}], "possibleAnswers": ["Yes, I read a few pages every night.", "Sometimes. My mum reads to me.", "I like reading in bed with a torch."]}, {"original": "Which book would you like to read again and again?", "paraphrased": "What is a book you never get bored of?", "vocab": [{"word": "again", "definition": "one more time", "translation": ""}, {"word": "bored", "definition": "when something is not interesting any more", "translation": ""}], "possibleAnswers": ["I would read my favourite animal comic again.", "The funny school story. It never gets old!", "I love reading the book about the magic map."]}]}, {"title": "My Hobbies (12 questions)", "slug": "myhobbies", "level": "A1-A2", "questions": [{"original": "What do you like to do when you are not at school?", "paraphrased": "How do you spend your time after class?", "vocab": [{"word": "hobby", "definition": "an activity you enjoy in your free time", "translation": ""}, {"word": "spend", "definition": "to use your time doing something", "translation": ""}], "possibleAnswers": ["I like drawing and playing football.", "I enjoy reading and listening to music.", "I play games and ride my bike."]}, {"original": "What do you make or collect in your hobby?", "paraphrased": "Do you create things or gather items as a hobby?", "vocab": [{"word": "make", "definition": "to create something with your hands", "translation": ""}, {"word": "collect", "definition": "to gather things you like, such as stamps", "translation": ""}], "possibleAnswers": ["I collect football cards. I have so many!", "I make bracelets for my friends.", "I collect shells from the beach."]}, {"original": "How long have you had your favourite hobby?", "paraphrased": "When did you start doing the hobby you love most?", "vocab": [{"word": "long", "definition": "a great amount of time", "translation": ""}, {"word": "start", "definition": "to begin doing something", "translation": ""}], "possibleAnswers": ["I have painted for three years.", "Since I was six. My dad taught me.", "About two years. I started at school."]}, {"original": "Do you like drawing or painting more, and why?", "paraphrased": "Which do you prefer: drawing or painting?", "vocab": [{"word": "drawing", "definition": "making pictures with a pencil or pen", "translation": ""}, {"word": "painting", "definition": "making pictures with a brush and colours", "translation": ""}], "possibleAnswers": ["I like drawing more. I love my pencils.", "Painting, because the colours are so bright.", "Drawing. I can do it anywhere, even outside."]}, {"original": "What hobby would you like to try next year?", "paraphrased": "Which new activity do you want to start soon?", "vocab": [{"word": "try", "definition": "to do something to see if you like it", "translation": ""}, {"word": "next", "definition": "the one that comes after this", "translation": ""}], "possibleAnswers": ["I would like to try photography.", "I want to learn to play the guitar.", "I would like to try baking cakes."]}, {"original": "Who taught you to do your favourite hobby?", "paraphrased": "Which person showed you how to do it?", "vocab": [{"word": "taught", "definition": "showed someone how to do something", "translation": ""}, {"word": "person", "definition": "a human being, like a friend or parent", "translation": ""}], "possibleAnswers": ["My grandma taught me to knit.", "My friend taught me to draw cartoons.", "My teacher taught me to play chess."]}, {"original": "Would you rather have a hobby inside or outside?", "paraphrased": "Do you prefer hobbies at home or in the open air?", "vocab": [{"word": "inside", "definition": "within a building", "translation": ""}, {"word": "outside", "definition": "in the open air, not indoors", "translation": ""}], "possibleAnswers": ["Outside! I love being in the sun.", "Inside, because I like quiet activities.", "Outside. I want to run and move."]}, {"original": "How much time do you spend on your hobby every week?", "paraphrased": "What is your weekly time for your favourite activity?", "vocab": [{"word": "time", "definition": "the hours and minutes you use for something", "translation": ""}, {"word": "week", "definition": "seven days, from Monday to Sunday", "translation": ""}], "possibleAnswers": ["About three hours every week.", "I spend an hour every day after school.", "Not much. Maybe two hours on the weekend."]}, {"original": "Do you collect anything, like stickers or cards?", "paraphrased": "Are there things you gather and keep?", "vocab": [{"word": "collect", "definition": "to gather and keep things you like", "translation": ""}, {"word": "stickers", "definition": "small pictures you stick onto things", "translation": ""}], "possibleAnswers": ["Yes, I collect stickers of animals.", "I collect cards from my favourite game.", "I do not collect things, but my brother does."]}, {"original": "What is something new you learned to do this year?", "paraphrased": "Which new skill did you learn recently?", "vocab": [{"word": "learned", "definition": "got new knowledge or skill by practising", "translation": ""}, {"word": "skill", "definition": "an ability you get by practice", "translation": ""}], "possibleAnswers": ["I learned to ride a bike without help.", "I learned to make pancakes with my mum.", "I learned a new dance at school."]}, {"original": "What is the best part of your favourite hobby?", "paraphrased": "Why do you enjoy your hobby the most?", "vocab": [{"word": "part", "definition": "one piece of a bigger thing", "translation": ""}, {"word": "enjoy", "definition": "to get pleasure from something", "translation": ""}], "possibleAnswers": ["The best part is making people smile.", "I love seeing my pictures on the wall.", "The best part is playing with my friends."]}, {"original": "If you had more free time, what would you do with it?", "paraphrased": "How would you use extra hours in your day?", "vocab": [{"word": "free", "definition": "with no work or duties; available", "translation": ""}, {"word": "extra", "definition": "more than what you already have", "translation": ""}], "possibleAnswers": ["I would read more books and comics.", "I would play football every day!", "I would learn to cook with my family."]}]}, {"title": "My Favourite Things (12 questions)", "slug": "myfavouritethings", "level": "A1-A2", "questions": [{"original": "If you could have any toy in the world, what would you choose?", "paraphrased": "What toy would you pick if anything was possible?", "vocab": [{"word": "toy", "definition": "an object children play with", "translation": ""}, {"word": "world", "definition": "the Earth and everything on it", "translation": ""}], "possibleAnswers": ["I would choose a big red racing car.", "A soft bear I can hug at night.", "I would choose a robot that can talk."]}, {"original": "On a rainy day, what do you like to do at home?", "paraphrased": "How do you spend a wet day indoors?", "vocab": [{"word": "rainy", "definition": "when water falls from the sky", "translation": ""}, {"word": "home", "definition": "the place where you live with your family", "translation": ""}], "possibleAnswers": ["I like reading comics and drinking hot chocolate.", "I play board games with my sister.", "I draw pictures and listen to music."]}, {"original": "Where is your favourite place to play in your town?", "paraphrased": "Which spot in your town do you enjoy most?", "vocab": [{"word": "place", "definition": "a location or area", "translation": ""}, {"word": "town", "definition": "a small city with houses and shops", "translation": ""}], "possibleAnswers": ["The park near my school. It has a great swing.", "My favourite place is the sports field.", "The library garden. It is quiet and pretty."]}, {"original": "What snack do you enjoy eating after school?", "paraphrased": "Which food do you like when classes end?", "vocab": [{"word": "snack", "definition": "a small amount of food between meals", "translation": ""}, {"word": "eat", "definition": "to put food in your mouth and swallow", "translation": ""}], "possibleAnswers": ["I enjoy fruit, like apples and bananas.", "A sandwich and a glass of milk.", "I love biscuits with chocolate."]}, {"original": "Which colour do you like the most, and why?", "paraphrased": "What is your top colour choice? Tell me why.", "vocab": [{"word": "colour", "definition": "how something looks, like red or blue", "translation": ""}, {"word": "like", "definition": "to enjoy or prefer something", "translation": ""}], "possibleAnswers": ["Blue, because it reminds me of the sea.", "I like green. It is the colour of trees.", "Pink! It makes me feel happy."]}, {"original": "Which day of the week do you like the most?", "paraphrased": "What is your best day of the week?", "vocab": [{"word": "day", "definition": "twenty-four hours, from morning to night", "translation": ""}, {"word": "week", "definition": "seven days, from Monday to Sunday", "translation": ""}], "possibleAnswers": ["Saturday, because I can play all day!", "Friday, because the weekend starts.", "Sunday, because we have lunch with family."]}, {"original": "Tell me about a toy you loved when you were small.", "paraphrased": "What toy did you adore as a little child?", "vocab": [{"word": "loved", "definition": "liked very much", "translation": ""}, {"word": "small", "definition": "little; not big or tall", "translation": ""}], "possibleAnswers": ["I loved a brown teddy bear called Benny.", "I had a toy train. It was my best friend!", "I loved a doll with yellow hair."]}, {"original": "Would you rather have a pet dog or a pet cat?", "paraphrased": "Do you prefer dogs or cats as pets?", "vocab": [{"word": "pet", "definition": "an animal you keep at home and care for", "translation": ""}, {"word": "rather", "definition": "used to show what you prefer", "translation": ""}], "possibleAnswers": ["A dog, because we can play in the park.", "A cat, because it is soft and quiet.", "I would rather have a rabbit!"]}, {"original": "What do you like to wear at home on cold days?", "paraphrased": "Which clothes do you choose when it is chilly?", "vocab": [{"word": "wear", "definition": "to have clothes on your body", "translation": ""}, {"word": "cold", "definition": "when the temperature is low; not warm", "translation": ""}], "possibleAnswers": ["I like warm pyjamas and thick socks.", "My soft hoodie and comfy trousers.", "I wear a big jumper and my slippers."]}, {"original": "Do you like summer or winter more for playing outside?", "paraphrased": "Which season do you prefer for outdoor games?", "vocab": [{"word": "summer", "definition": "the warmest season of the year", "translation": ""}, {"word": "winter", "definition": "the coldest season of the year", "translation": ""}], "possibleAnswers": ["Summer! I can swim and play all day.", "Winter, because I love the snow.", "Summer, because the days are long."]}, {"original": "What is the best thing about your favourite school subject?", "paraphrased": "Why do you enjoy your favourite lesson?", "vocab": [{"word": "subject", "definition": "a thing you study, like maths or art", "translation": ""}, {"word": "lesson", "definition": "a period of learning at school", "translation": ""}], "possibleAnswers": ["Art is fun because I can draw and paint.", "I love English. We read great stories.", "Science is exciting. We do fun experiments."]}, {"original": "How do you like to spend time with your family at the weekend?", "paraphrased": "What do you enjoy doing with your family on weekends?", "vocab": [{"word": "weekend", "definition": "Saturday and Sunday, when there is no school", "translation": ""}, {"word": "family", "definition": "the people you live with who love you", "translation": ""}], "possibleAnswers": ["We play board games and eat together.", "We go to the park or the beach.", "We watch a film and make popcorn."]}]}]}, {"category": "The World Around Me", "topics": [{"title": "Animals and Nature (12 questions)", "slug": "animalsandnature", "level": "A1-A2", "questions": [{"original": "What is your favourite animal? Why do you like it?", "paraphrased": "Which animal do you like best, and what do you like about it?", "vocab": [{"word": "animal", "definition": "A living thing that moves and eats, like a dog, bird, or fish.", "translation": ""}, {"word": "favourite", "definition": "The one you like more than all the others.", "translation": ""}], "possibleAnswers": ["My favourite animal is the dolphin because it is clever and friendly.", "I like rabbits because they are small and soft.", "I love elephants. They are big, but they are very kind."]}, {"original": "Have you ever seen a wild animal? What was it?", "paraphrased": "Have you seen an animal living outside, not in a house? Which one?", "vocab": [{"word": "wild", "definition": "Living free outside, not looked after by people.", "translation": ""}, {"word": "seen", "definition": "You saw it with your eyes.", "translation": ""}], "possibleAnswers": ["Yes, I saw a fox in the park near my home.", "I saw many wild ducks on a lake with my dad.", "No, I have never seen a wild animal, but I want to."]}, {"original": "What animals live on a farm? Which one do you like?", "paraphrased": "Which animals can you find on a farm? Do you have a favourite one?", "vocab": [{"word": "farm", "definition": "A place where people keep animals and grow food.", "translation": ""}, {"word": "live", "definition": "To stay or make your home in a place.", "translation": ""}], "possibleAnswers": ["Cows, sheep and chickens live on a farm. I like the sheep.", "I like the horses because I can ride them.", "A farm has pigs and ducks too. The ducks are funny."]}, {"original": "Do you have a pet at home? What is its name?", "paraphrased": "Is there a pet in your house? What do you call it?", "vocab": [{"word": "pet", "definition": "An animal you keep at home and look after, like a cat.", "translation": ""}, {"word": "name", "definition": "The word you use to call someone or something.", "translation": ""}], "possibleAnswers": ["Yes, I have a cat and her name is Luna.", "I have a small dog called Max. He sleeps on my bed.", "No, I do not have a pet, but I would like a rabbit."]}, {"original": "What do you like to do in a park or forest?", "paraphrased": "When you are outside in nature, what do you enjoy doing?", "vocab": [{"word": "forest", "definition": "A big place with many trees and animals.", "translation": ""}, {"word": "enjoy", "definition": "To like doing something very much.", "translation": ""}], "possibleAnswers": ["I like walking with my family and looking at the birds.", "I play football in the park with my friends.", "I like sitting under a tree and reading a book."]}, {"original": "Which animal do you think is the most helpful? Why?", "paraphrased": "What animal helps people the most? Can you tell me why?", "vocab": [{"word": "helpful", "definition": "Giving help to people when they need it.", "translation": ""}, {"word": "think", "definition": "To have an idea or opinion about something.", "translation": ""}], "possibleAnswers": ["I think dogs are the most helpful because they help people.", "Bees are helpful too. They help flowers and fruit grow.", "Horses help farmers and carry heavy things."]}, {"original": "What bird or insect do you see near your home?", "paraphrased": "Which small flying animal do you notice around where you live?", "vocab": [{"word": "bird", "definition": "An animal with feathers and wings that can often fly.", "translation": ""}, {"word": "insect", "definition": "A very small animal with six legs, like a bee.", "translation": ""}], "possibleAnswers": ["I see pigeons and sparrows every morning near my window.", "There are many bees in our garden in summer.", "I see butterflies on the flowers near my school."]}, {"original": "Would you like to swim with dolphins one day? Why?", "paraphrased": "Do you dream of swimming with dolphins? What makes you say yes or no?", "vocab": [{"word": "swim", "definition": "To move through water using your arms and legs.", "translation": ""}, {"word": "dream", "definition": "Something you really hope will happen one day.", "translation": ""}], "possibleAnswers": ["Yes, I would love it because dolphins are friendly and clever.", "No, I am a little afraid of big animals in the sea.", "Maybe yes, but only if my mum goes with me."]}, {"original": "What do you do to help animals in your town?", "paraphrased": "How do you care for animals around where you live?", "vocab": [{"word": "help", "definition": "To do something kind for someone or something.", "translation": ""}, {"word": "town", "definition": "The place where you live, with houses and shops.", "translation": ""}], "possibleAnswers": ["I give water to the birds in our garden.", "My family takes our old blankets to the animal centre.", "I never scare cats and dogs on the street."]}, {"original": "Which season is best for watching animals? Tell me why.", "paraphrased": "When do you see the most animals outside? Can you explain?", "vocab": [{"word": "season", "definition": "A part of the year, like spring, summer, autumn or winter.", "translation": ""}, {"word": "watching", "definition": "Looking at something for a while because it is interesting.", "translation": ""}], "possibleAnswers": ["Spring, because the baby animals come out with their mothers.", "Summer is best. I see many birds and insects then.", "Autumn, because the ducks come back to our lake."]}, {"original": "If you could be any animal for a day, which one?", "paraphrased": "Imagine you can be an animal for one day. What do you choose?", "vocab": [{"word": "could", "definition": "A word we use to talk about something possible or imaginary.", "translation": ""}, {"word": "choose", "definition": "To pick the one you want.", "translation": ""}], "possibleAnswers": ["I would be an eagle because I want to fly high.", "I would be a cat and sleep all day in the sun.", "I would be a dolphin and swim in the warm sea."]}, {"original": "What is a safe and kind way to behave near animals?", "paraphrased": "How should we act around animals so they feel calm and happy?", "vocab": [{"word": "safe", "definition": "Not dangerous; nothing bad will happen.", "translation": ""}, {"word": "kind", "definition": "Being gentle, friendly and caring.", "translation": ""}], "possibleAnswers": ["We should be quiet and slow, and never pull their tails.", "Always ask the owner first, then touch the animal gently.", "Give them space to eat and sleep without noise."]}]}, {"title": "Weather and Seasons (12 questions)", "slug": "weatherandseasons", "level": "A1-A2", "questions": [{"original": "What is your favourite season? What do you do in it?", "paraphrased": "Which time of year do you like most? How do you spend it?", "vocab": [{"word": "season", "definition": "A part of the year, like spring, summer, autumn or winter.", "translation": ""}, {"word": "spend", "definition": "To use your time doing something.", "translation": ""}], "possibleAnswers": ["I like summer best because I swim in the sea with my family.", "My favourite is winter. I drink hot chocolate by the window.", "Spring is lovely. I ride my bike and watch the flowers open."]}, {"original": "What is the weather like today where you live?", "paraphrased": "Is it sunny, rainy or cold outside your home right now?", "vocab": [{"word": "weather", "definition": "What the sky and air are like: sunny, rainy, cold or windy.", "translation": ""}, {"word": "sunny", "definition": "Bright with sunshine and a clear sky.", "translation": ""}], "possibleAnswers": ["It is sunny and warm, so I am playing outside.", "It is cloudy and a little cold. I am wearing my jacket.", "It is raining, so we are staying inside today."]}, {"original": "What do you like to do when it rains?", "paraphrased": "On a rainy day, what do you enjoy doing inside or outside?", "vocab": [{"word": "rain", "definition": "Water that falls from the clouds.", "translation": ""}, {"word": "inside", "definition": "In the house, not outdoors.", "translation": ""}], "possibleAnswers": ["I read comics and listen to the rain on the window.", "I like jumping in puddles with my boots.", "I draw pictures or play a game with my brother."]}, {"original": "Do you prefer hot weather or cold weather? Why?", "paraphrased": "Would you rather be warm or chilly? What do you say?", "vocab": [{"word": "prefer", "definition": "To like one thing more than another.", "translation": ""}, {"word": "warm", "definition": "A nice heat, not too hot and not cold.", "translation": ""}], "possibleAnswers": ["I prefer warm weather because I can play outside longer.", "I like cold weather. I enjoy wearing a scarf and boots.", "Warm is better for me because I love swimming."]}, {"original": "What clothes do you wear when it is very cold?", "paraphrased": "On freezing days, what do you put on to stay cosy?", "vocab": [{"word": "clothes", "definition": "The things you wear, like shirts, coats and socks.", "translation": ""}, {"word": "cold", "definition": "When the air is low in temperature and you need a coat.", "translation": ""}], "possibleAnswers": ["I wear a warm coat, a hat, gloves and thick socks.", "I put on my big jumper and my scarf.", "I wear boots so my feet stay warm and dry."]}, {"original": "Have you ever played in the snow? What did you do?", "paraphrased": "Did you ever have fun outside in snow? Tell me about it.", "vocab": [{"word": "snow", "definition": "Soft white frozen water that falls in very cold weather.", "translation": ""}, {"word": "fun", "definition": "Enjoyable and makes you smile.", "translation": ""}], "possibleAnswers": ["Yes, I made a snowman with my sister last year.", "I threw soft snowballs with my friends, and we laughed.", "No, it never snows here, but I would love to see it."]}, {"original": "What do you see in the sky on a clear night?", "paraphrased": "When the sky is dark and clear, what can you notice up there?", "vocab": [{"word": "sky", "definition": "The blue space above us where we see the sun, clouds and stars.", "translation": ""}, {"word": "stars", "definition": "Small bright lights we see in the night sky.", "translation": ""}], "possibleAnswers": ["I see the moon and many bright stars with my grandma.", "Sometimes I see a plane moving slowly across the sky.", "I like finding the Big Dipper with my dad."]}, {"original": "Which season do you think has the best food? Why?", "paraphrased": "When do you eat the tastiest things? Can you say why?", "vocab": [{"word": "food", "definition": "What we eat to live and grow, like bread, fruit and rice.", "translation": ""}, {"word": "tasty", "definition": "Having a nice flavour that you enjoy eating.", "translation": ""}], "possibleAnswers": ["Summer, because we eat cold watermelon and sweet strawberries.", "Autumn is best. We bake apples and pears with my mum.", "Winter, because warm soup and bread taste so good."]}, {"original": "What is your favourite thing to do on a sunny day?", "paraphrased": "When the sun is shining, what makes you happiest to do?", "vocab": [{"word": "sunny", "definition": "Bright with sunshine and a clear sky.", "translation": ""}, {"word": "happiest", "definition": "Feeling the most joy and smiles.", "translation": ""}], "possibleAnswers": ["I ride my bike to the park with my best friend.", "I have a picnic with sandwiches and juice outside.", "I play in the garden and water the flowers."]}, {"original": "How does the weather change the way you feel?", "paraphrased": "Does sun, rain or cold make you feel different? How?", "vocab": [{"word": "change", "definition": "To become different from before.", "translation": ""}, {"word": "feel", "definition": "To have an emotion, like happy, tired or calm.", "translation": ""}], "possibleAnswers": ["Sunshine makes me feel happy and full of energy.", "Rainy days make me calm, so I like reading at home.", "When it is cold I feel sleepy and want a warm drink."]}, {"original": "Would you rather have a long summer or a long winter?", "paraphrased": "Imagine you can pick a longer summer or winter. Which one?", "vocab": [{"word": "rather", "definition": "A way to say you would prefer one thing.", "translation": ""}, {"word": "long", "definition": "Lasting for many weeks or hours.", "translation": ""}], "possibleAnswers": ["A long summer, because I can swim and play outside every day.", "A long winter sounds nice. I love snow and hot soup.", "A long summer, but I also want a short snowy week."]}, {"original": "What do you watch or listen to on a windy day?", "paraphrased": "When the wind blows hard, what do you enjoy seeing or hearing?", "vocab": [{"word": "windy", "definition": "When the air moves fast outside and blows things around.", "translation": ""}, {"word": "listen", "definition": "To pay attention to a sound.", "translation": ""}], "possibleAnswers": ["I watch the trees dance and my kite fly high.", "I listen to the wind sing around the windows.", "I like watching clouds move quickly across the sky."]}]}, {"title": "Holidays and Travel (12 questions)", "slug": "holidaysandtravel", "level": "A1-A2", "questions": [{"original": "Have you ever been on a long trip? Where did you go?", "paraphrased": "Did you ever travel far from home? Tell me about the place.", "vocab": [{"word": "trip", "definition": "A journey you take to visit another place.", "translation": ""}, {"word": "travel", "definition": "To go on a journey to a different place.", "translation": ""}], "possibleAnswers": ["Yes, we went to the mountains for one week.", "I travelled by train to see my grandma in another city.", "Not yet, but my family plans a trip to the sea."]}, {"original": "What is your favourite holiday? How do you celebrate it?", "paraphrased": "Which special day do you love most? What do you do on it?", "vocab": [{"word": "holiday", "definition": "A special day or time when you do not go to school.", "translation": ""}, {"word": "celebrate", "definition": "To do happy things for a special day.", "translation": ""}], "possibleAnswers": ["I love birthdays. We eat cake and play games together.", "Christmas is my favourite. We give presents and sing songs.", "Eid is special for us. We visit family and eat tasty food."]}, {"original": "Would you rather go to the beach or the mountains?", "paraphrased": "Imagine a holiday by the sea or in the hills. Which one?", "vocab": [{"word": "beach", "definition": "The sandy place next to the sea where you can swim.", "translation": ""}, {"word": "mountains", "definition": "Very high hills, often with rocks, trees and snow.", "translation": ""}], "possibleAnswers": ["I would choose the beach because I love swimming.", "The mountains, please. I like walking and clean air.", "The beach, but I also want to see the mountains one day."]}, {"original": "What do you pack in your bag for a holiday?", "paraphrased": "When you go away, what things do you put in your suitcase?", "vocab": [{"word": "pack", "definition": "To put your things into a bag before a trip.", "translation": ""}, {"word": "bag", "definition": "Something you use to carry your things, like a suitcase.", "translation": ""}], "possibleAnswers": ["I pack my clothes, my toothbrush and my favourite book.", "I put in my hat, my camera and some snacks.", "I always pack my swimwear and my soft toy."]}, {"original": "How do you like to travel: by car, bus, train or plane?", "paraphrased": "Which way of travelling do you enjoy most, and why?", "vocab": [{"word": "train", "definition": "A long vehicle that moves on metal tracks.", "translation": ""}, {"word": "plane", "definition": "A flying vehicle that takes people to far places.", "translation": ""}], "possibleAnswers": ["I like the train because I can look out of the window.", "The plane is exciting. I love watching the clouds.", "By car is best for me. We sing songs on the way."]}, {"original": "What is the best place you have ever visited? Why?", "paraphrased": "Which place did you enjoy most on your trips? Tell me why.", "vocab": [{"word": "place", "definition": "A location, like a town, beach or park.", "translation": ""}, {"word": "visited", "definition": "You went to see a place for a short time.", "translation": ""}], "possibleAnswers": ["The lake near my grandma's house. We fed the ducks there.", "I loved the zoo because I saw many animals up close.", "The old town in our city. The buildings were so pretty."]}, {"original": "Do you prefer holidays with family or with friends?", "paraphrased": "Would you rather go away with your family or your friends?", "vocab": [{"word": "family", "definition": "The people in your home, like your parents and siblings.", "translation": ""}, {"word": "friends", "definition": "People you like and enjoy spending time with.", "translation": ""}], "possibleAnswers": ["With my family, because we laugh and cook together.", "I like going with my best friend. We play all day.", "Both are great, but family trips feel warmer."]}, {"original": "What do you like to eat when you are on holiday?", "paraphrased": "When you travel, what food do you enjoy trying?", "vocab": [{"word": "eat", "definition": "To put food in your mouth and swallow it.", "translation": ""}, {"word": "trying", "definition": "Testing something new to see if you like it.", "translation": ""}], "possibleAnswers": ["I love ice cream on the beach with my brother.", "I like trying new fruit from the market.", "We eat fresh bread and cheese for breakfast."]}, {"original": "What would you show a visitor in your country?", "paraphrased": "If a friend came to your country, where would you take them?", "vocab": [{"word": "visitor", "definition": "A person who comes to see a place or stay with you.", "translation": ""}, {"word": "country", "definition": "The land where you live, with its own cities and people.", "translation": ""}], "possibleAnswers": ["I would show them our big park and the old market.", "I would take them to see the sea and the pretty boats.", "I would show them the museum and our best ice cream shop."]}, {"original": "Have you ever stayed in a hotel? What was it like?", "paraphrased": "Did you sleep in a hotel on a trip? How was it?", "vocab": [{"word": "hotel", "definition": "A building where travellers sleep and eat.", "translation": ""}, {"word": "stayed", "definition": "You slept or lived somewhere for a short time.", "translation": ""}], "possibleAnswers": ["Yes, our hotel had a pool and a big breakfast.", "It was small but clean, and I liked the soft bed.", "No, we always stay with my aunt when we travel."]}, {"original": "What do you take with you to remember a trip?", "paraphrased": "How do you keep nice memories of a journey?", "vocab": [{"word": "remember", "definition": "To keep a picture or feeling in your mind.", "translation": ""}, {"word": "memories", "definition": "Happy thoughts about things that happened before.", "translation": ""}], "possibleAnswers": ["I take many photos and keep tickets in a box.", "I draw a small picture of the place in my notebook.", "I buy a little key ring from every town I visit."]}, {"original": "Where do you want to travel next? What do you want to see?", "paraphrased": "What is your dream trip? Which place and what would you look for?", "vocab": [{"word": "next", "definition": "The one after this one; coming soon.", "translation": ""}, {"word": "dream", "definition": "Something you really hope for and imagine.", "translation": ""}], "possibleAnswers": ["I want to visit Egypt and see the big pyramids.", "Next I want to see the snowy mountains and ski.", "I dream of Japan. I want to see the cherry flowers."]}]}, {"title": "When I Grow Up (12 questions)", "slug": "whenigrowup", "level": "A1-A2", "questions": [{"original": "What do you want to be when you grow up?", "paraphrased": "When you are older, what job do you hope to have?", "vocab": [{"word": "grow up", "definition": "To become an adult over many years.", "translation": ""}, {"word": "job", "definition": "The work you do to earn money and help people.", "translation": ""}], "possibleAnswers": ["I want to be a teacher because I love helping children learn.", "I would like to be a doctor and help sick people.", "I want to be a pilot and fly planes around the world."]}, {"original": "What subject at school do you enjoy the most? Why?", "paraphrased": "Which lesson makes you happiest? Can you tell me why?", "vocab": [{"word": "subject", "definition": "A thing you study at school, like maths or art.", "translation": ""}, {"word": "enjoy", "definition": "To like doing something very much.", "translation": ""}], "possibleAnswers": ["I enjoy art because I love drawing and using colours.", "Science is my favourite. I like doing fun experiments.", "I like English because I can read stories and write my own."]}, {"original": "Who is a person you admire? What do they do?", "paraphrased": "Which person do you look up to? What makes them special?", "vocab": [{"word": "admire", "definition": "To respect and think well of someone.", "translation": ""}, {"word": "special", "definition": "Different from others in a good way.", "translation": ""}], "possibleAnswers": ["I admire my mum. She works hard and is always kind.", "I look up to my football coach. He teaches us to be brave.", "I admire my science teacher because she makes lessons fun."]}, {"original": "What new skill would you like to learn one day?", "paraphrased": "Is there something you cannot do yet but want to learn?", "vocab": [{"word": "skill", "definition": "Something you can do well after learning and practising.", "translation": ""}, {"word": "learn", "definition": "To get new knowledge or ability by studying or doing.", "translation": ""}], "possibleAnswers": ["I would like to learn to play the guitar.", "I want to learn how to cook pasta with my grandma.", "I would love to learn to swim fast like a fish."]}, {"original": "Do you prefer working alone or with other people?", "paraphrased": "Would you rather do a task by yourself or in a group?", "vocab": [{"word": "alone", "definition": "With no other people; just by yourself.", "translation": ""}, {"word": "group", "definition": "A number of people working or playing together.", "translation": ""}], "possibleAnswers": ["I like working with others because we share ideas.", "I prefer alone. I can think quietly and work slowly.", "Both are fine, but I enjoy talking with my team."]}, {"original": "What would you do if you could help your town?", "paraphrased": "Imagine you can make your town better. What would you do?", "vocab": [{"word": "help", "definition": "To do something useful for someone or a place.", "translation": ""}, {"word": "better", "definition": "Good, and then even more good than before.", "translation": ""}], "possibleAnswers": ["I would plant more trees and flowers in the park.", "I would help clean the beach with my class.", "I would make a small library for children near the school."]}, {"original": "What kind of work do your parents do every day?", "paraphrased": "What jobs do your mum and dad have? What do they do?", "vocab": [{"word": "parents", "definition": "Your mother and father.", "translation": ""}, {"word": "work", "definition": "The tasks you do as a job.", "translation": ""}], "possibleAnswers": ["My mum is a nurse and she helps people in hospital.", "My dad works in an office and uses a computer.", "My parents work in a shop and help customers."]}, {"original": "Would you like to work with animals or with children?", "paraphrased": "Imagine a job with animals or with kids. Which do you pick?", "vocab": [{"word": "animals", "definition": "Living things like dogs, cats, birds and fish.", "translation": ""}, {"word": "children", "definition": "Young people who are not adults yet.", "translation": ""}], "possibleAnswers": ["I would work with animals because I love them so much.", "With children, please. I like playing and teaching them.", "Animals, but I also want to read stories to children."]}, {"original": "What do you think makes a good teacher? Why?", "paraphrased": "What should a great teacher be like? Can you explain?", "vocab": [{"word": "teacher", "definition": "A person who helps you learn at school.", "translation": ""}, {"word": "good", "definition": "Having nice qualities and doing things well.", "translation": ""}], "possibleAnswers": ["A good teacher is kind and listens to every student.", "I think a good teacher makes lessons fun and clear.", "A good teacher is patient and never shouts at us."]}, {"original": "If you could invent something, what would it be?", "paraphrased": "Imagine you can create a new thing. What do you make?", "vocab": [{"word": "invent", "definition": "To make something new that did not exist before.", "translation": ""}, {"word": "create", "definition": "To make or build something.", "translation": ""}], "possibleAnswers": ["I would invent a robot that cleans my room for me.", "I would make a flying bike so I never wait for a bus.", "I would invent a pen that helps you write in any language."]}, {"original": "What do you want to be good at by the age of twenty?", "paraphrased": "When you are twenty, what skill do you hope to have?", "vocab": [{"word": "good at", "definition": "Able to do something well.", "translation": ""}, {"word": "age", "definition": "How many years old you are.", "translation": ""}], "possibleAnswers": ["I want to be good at speaking English and making friends.", "I hope I am good at cooking healthy meals for my family.", "I want to be good at drawing and making cartoons."]}, {"original": "What is one small step you can take this week to reach your dream?", "paraphrased": "What easy thing can you do now to get closer to your goal?", "vocab": [{"word": "step", "definition": "One small action that helps you move forward.", "translation": ""}, {"word": "goal", "definition": "Something you work hard to achieve.", "translation": ""}], "possibleAnswers": ["I can read a book about scientists for twenty minutes.", "I will practise drawing every day after school.", "I can ask my teacher how to be a better speaker."]}]}, {"title": "My Town or Village (12 questions)", "slug": "myneighbourhood", "level": "A1-A2", "questions": [{"original": "What is your favourite thing about your town?", "paraphrased": "Which part of where you live do you like best?", "vocab": [{"word": "town", "definition": "A place with houses, shops and schools where people live.", "translation": ""}, {"word": "favourite", "definition": "The one you like more than all the others.", "translation": ""}], "possibleAnswers": ["I love the big park where I play with my friends.", "My favourite thing is the library near my school.", "I like the market because it is busy and colourful."]}, {"original": "Where do you go to buy food near your home?", "paraphrased": "Which shop or market do you visit for food?", "vocab": [{"word": "buy", "definition": "To get something by paying money for it.", "translation": ""}, {"word": "shop", "definition": "A small building where you buy things.", "translation": ""}], "possibleAnswers": ["We go to the small shop on the corner for bread and milk.", "My mum buys fruit and vegetables at the market.", "There is a supermarket near our bus stop."]}, {"original": "Is your street quiet or busy? What do you hear there?", "paraphrased": "Does your road have lots of people and cars, or is it calm?", "vocab": [{"word": "street", "definition": "A road in a town with houses or shops on each side.", "translation": ""}, {"word": "busy", "definition": "Full of people, cars and activity.", "translation": ""}], "possibleAnswers": ["My street is quiet. I hear birds and children playing.", "It is busy in the morning with cars and buses.", "It is quiet at night, but busy on Saturday."]}, {"original": "What places do you visit with your friends after school?", "paraphrased": "Where do you and your friends like to go when lessons end?", "vocab": [{"word": "places", "definition": "Locations or spots, like a park or a café.", "translation": ""}, {"word": "after school", "definition": "The time when your lessons are finished for the day.", "translation": ""}], "possibleAnswers": ["We go to the park and play football together.", "We like the café near school for a juice and a chat.", "We sometimes go to the library to read comics."]}, {"original": "Do you live near a park, a river or a forest?", "paraphrased": "Is there green space or water close to your house?", "vocab": [{"word": "near", "definition": "Close to; not far away.", "translation": ""}, {"word": "river", "definition": "A long line of water that moves across the land.", "translation": ""}], "possibleAnswers": ["Yes, there is a park near my house. I go there every day.", "We live near a small river. I watch the ducks there.", "No, but there is a big forest about twenty minutes away."]}, {"original": "What do you like to do in your neighbourhood on weekends?", "paraphrased": "How do you spend your Saturday and Sunday near home?", "vocab": [{"word": "neighbourhood", "definition": "The area around your home where you know people.", "translation": ""}, {"word": "weekend", "definition": "Saturday and Sunday, when you do not go to school.", "translation": ""}], "possibleAnswers": ["I ride my bike and visit the small shop for sweets.", "We walk the dog and meet our neighbours.", "I play games in the park with my best friend."]}, {"original": "Would you rather live near the sea or near the mountains?", "paraphrased": "Imagine living close to water or high hills. Which one?", "vocab": [{"word": "sea", "definition": "The big salt water that covers much of the Earth.", "translation": ""}, {"word": "live", "definition": "To have your home in a place.", "translation": ""}], "possibleAnswers": ["Near the sea, because I love swimming and sandy beaches.", "Near the mountains. I like fresh air and walking.", "The sea, but I also want to visit the mountains."]}, {"original": "What would you change to make your town nicer?", "paraphrased": "If you could improve one thing at home, what would it be?", "vocab": [{"word": "change", "definition": "To make something different from how it is now.", "translation": ""}, {"word": "nicer", "definition": "More pleasant, clean and friendly.", "translation": ""}], "possibleAnswers": ["I would add more bins so the streets stay clean.", "I would plant more flowers and trees in the park.", "I would make a safe path for bikes near the school."]}, {"original": "Who are your neighbours? Do you know them well?", "paraphrased": "What are the people next to your home like? Do you talk to them?", "vocab": [{"word": "neighbours", "definition": "People who live close to your home.", "translation": ""}, {"word": "talk", "definition": "To speak with someone.", "translation": ""}], "possibleAnswers": ["Our neighbours are a kind family with two children.", "Yes, we say hello and sometimes share food.", "We know them a little, but we do not visit often."]}, {"original": "How do you get from your home to your school?", "paraphrased": "What way do you travel to school each morning?", "vocab": [{"word": "get", "definition": "To arrive or reach a place.", "translation": ""}, {"word": "school", "definition": "The place where you go to learn every day.", "translation": ""}], "possibleAnswers": ["I walk to school with my sister. It takes ten minutes.", "My dad drives me in the car on his way to work.", "I take the bus with my friends from the corner."]}, {"original": "What is the best thing about living in a small village?", "paraphrased": "Why can life in a small village feel good?", "vocab": [{"word": "village", "definition": "A very small group of houses in the countryside.", "translation": ""}, {"word": "best", "definition": "The most good of all.", "translation": ""}], "possibleAnswers": ["It is quiet and everyone knows each other.", "There are many trees and animals near my house.", "I can play outside safely with my friends."]}, {"original": "If a new child moved to your street, what would you show them?", "paraphrased": "Imagine a new friend comes to live near you. Where would you take them?", "vocab": [{"word": "new", "definition": "Not known before; recently arrived.", "translation": ""}, {"word": "show", "definition": "To take someone to see a place.", "translation": ""}], "possibleAnswers": ["I would show them the park and the best place for ice cream.", "I would take them to the library and the school.", "I would introduce them to my friends in the street."]}]}]}];
